long write_carried(const char* root) { maca_make_dir(root); { MacaList _f = CarriedPackages; for (int _fi = 0; _fi < _f.len; _fi++) { const char* pkg = ((const char*)_f.data[_fi]); maca_make_dir(maca_cat(maca_cat(maca_cat("", root), "/"), pkg)); } } const char* std_csv = "// std/csv: comma-separated values, RFC 4180 as far as it is worth going.\n\nimport std/text\n\n/// One field, quoted only when it has to be.\nfield(s: str) -> str {\n    if needs_quotes(s) {\n        \"\\\"\" ++ s.replace(\"\\\"\", \"\\\"\\\"\") ++ \"\\\"\"\n    } else {\n        s\n    }\n}\n\nneeds_quotes(s: str) -> bool =>\n    s.contains(\",\") || s.contains(\"\\\"\") || s.contains(\"\\n\")\n        || s.contains(\"\\r\")\n\n/// One record, terminated with `\\r\\n`.\nrow(cells: str[]) -> str =>\n    cells.map(field).join(\",\") ++ \"\\r\\n\"\n\n/// A whole document from a header and its rows.\ndocument(header: str[], rows: str[][]) -> str =>\n    row(header) ++ join_rows(rows, 0, \"\")\n\njoin_rows(rows: str[][], i: int, acc: str) -> str {\n    if i >= rows.length() {\n        acc\n    } else {\n        join_rows(rows, i + 1, acc ++ row(rows.get(i)))\n    }\n}\n\n/// The fields of one record.\nparse_row(line: str) -> str[] =>\n    scan_fields(line.chars(), 0, \"\", [])\n\nscan_fields(cs: str[], i: int, cur: str, acc: str[]) -> str[] {\n    if i >= cs.length() {\n        acc.push(cur)\n    } else {\n        next_field(cs, i, cur, acc)\n    }\n}\n\nnext_field(cs: str[], i: int, cur: str, acc: str[]) -> str[] {\n    c = cs.get(i)\n\n    if c == \"\\\"\" {\n        read_quoted_field(cs, i + 1, cur, acc)\n    } else if c == \",\" {\n        scan_fields(cs, i + 1, \"\", acc.push(cur))\n    } else if c == \"\\r\" {\n        scan_fields(cs, i + 1, cur, acc)\n    } else {\n        scan_fields(cs, i + 1, cur ++ c, acc)\n    }\n}\n\nread_quoted_field(cs: str[], i: int, cur: str, acc: str[]) -> str[] {\n    if i >= cs.length() {\n        acc.push(cur)\n    } else if cs.get(i) != \"\\\"\" {\n        read_quoted_field(cs, i + 1, cur ++ cs.get(i), acc)\n    } else if i + 1 < cs.length() && cs.get(i + 1) == \"\\\"\" {\n        read_quoted_field(cs, i + 2, cur ++ \"\\\"\", acc)\n    } else {\n        scan_fields(cs, i + 1, cur, acc)\n    }\n}\n\n/// Every record in a document.\nparse(src: str) -> str[][] =>\n    parse_rows(split_records(src.chars(), 0, false, \"\", []), 0, [])\n\nparse_rows(ls: str[], i: int, acc: str[][]) -> str[][] {\n    if i >= ls.length() {\n        acc\n    } else if ls.get(i).trim() == \"\" {\n        parse_rows(ls, i + 1, acc)\n    } else {\n        parse_rows(ls, i + 1, acc.push(parse_row(ls.get(i))))\n    }\n}\n\nsplit_records(cs: str[], i: int, in_q: bool, cur: str, acc: str[]) -> str[] {\n    if i < cs.length() {\n        record_step(cs, i, in_q, cur, acc)\n    } else if cur == \"\" {\n        acc\n    } else {\n        acc.push(cur)\n    }\n}\n\nrecord_step(cs: str[], i: int, in_q: bool, cur: str, acc: str[]) -> str[] {\n    c = cs.get(i)\n\n    if c == \"\\\"\" {\n        split_records(cs, i + 1, !in_q, cur ++ c, acc)\n    } else if c == \"\\n\" && !in_q {\n        split_records(cs, i + 1, in_q, \"\", acc.push(cur))\n    } else {\n        split_records(cs, i + 1, in_q, cur ++ c, acc)\n    }\n}\n\n/// The value under `name` in `row`, using `header` for the column order.\ncolumn(header: str[], row: str[], name: str) -> str {\n    at = header.index_of(name)\n\n    if at < 0 || at >= row.length() {\n        \"\"\n    } else {\n        row.get(at)\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/std/csv.maca"), std_csv); const char* std_fs = "// std/fs: the filesystem work a build step keeps rewriting.\n\nimport std/text\nimport std/path\n\n/// Every file under `root`, recursively, in a stable order.\nwalk(root: str) -> str[] =>\n    walk_entries(root, list_dir(root), 0, [])\n\nwalk_entries(root: str, names: str[], i: int, acc: str[]) -> str[] {\n    if i >= names.length() {\n        acc\n    } else {\n        found = walk_one(join(root, names.get(i)))\n        walk_entries(root, names, i + 1, acc ++ found)\n    }\n}\n\nwalk_one(p: str) -> str[] {\n    if is_dir(p) {\n        walk(p)\n    } else {\n        [p]\n    }\n}\n\n/// Directories under `root`, recursively.\nwalk_dirs(root: str) -> str[] =>\n    dir_entries(root, list_dir(root), 0, [])\n\ndir_entries(root: str, names: str[], i: int, acc: str[]) -> str[] {\n    if i >= names.length() {\n        acc\n    } else {\n        found = dir_one(join(root, names.get(i)))\n        dir_entries(root, names, i + 1, acc ++ found)\n    }\n}\n\ndir_one(p: str) -> str[] {\n    if is_dir(p) {\n        [p] ++ walk_dirs(p)\n    } else {\n        []\n    }\n}\n\n/// Files under `root` whose name ends with `suffix`.\nfind(root: str, suffix: str) -> str[] =>\n    walk(root).filter(p => p.ends_with(suffix))\n\n/// A file's lines, without terminators.\nread_lines(p: str) -> str[] =>\n    lines(read_file(p))\n\n/// Write `text` to `p`, creating the parent directory.\nwrite_if_changed(p: str, text: str) -> bool {\n    unchanged = file_exists(p) && read_file(p) == text\n\n    if unchanged {\n        false\n    } else {\n        force_write(p, text)\n    }\n}\n\nforce_write(p: str, text: str) -> bool {\n    make_dir(dirname(p))\n    write_file(p, text)\n}\n\n/// Append, creating the file if it isn't there.\nappend_file(p: str, text: str) -> bool {\n    existing = if file_exists(p) { read_file(p) } else { \"\" }\n\n    write_file(p, existing ++ text)\n}\n\n/// A byte-for-byte copy, not `write_file(to, read_file(from))`, which stops at the first NUL and so turns copying a wasm module or an image into silently truncating it.\ncopy_file(from: str, to: str) -> bool {\n    make_dir(dirname(to))\n    copy_bytes(from, to)\n}\n\n/// Copy a tree, preserving the layout under `to`.\ncopy_tree(from: str, to: str) -> int =>\n    copy_all(from, to, walk(from), 0, 0)\n\ncopy_all(from: str, to: str, files: str[], i: int, n: int) -> int {\n    if i >= files.length() {\n        n\n    } else {\n        copied = if copy_one(files.get(i), from, to) { 1 } else { 0 }\n        copy_all(from, to, files, i + 1, n + copied)\n    }\n}\n\ncopy_one(p: str, from: str, to: str) -> bool {\n    rel = strip_prefix(strip_prefix(p, from), \"/\")\n    copy_file(p, join(to, rel))\n}\n\n/// The size of a whole tree, in bytes.\ntree_size(root: str) -> int =>\n    walk(root).map(p => file_size(p)).sum()\n"; maca_write_file(maca_cat(maca_cat("", root), "/std/fs.maca"), std_fs); const char* std_json = "// std/json: JSON, written in Maca.\n//\n// Two halves. `encode` and `decode` are the typed pair: the compiler writes\n// them from the record and sum types the program declares, so a page never\n// spells a field twice. Everything else here reads and writes JSON as text,\n// for the shapes no type describes.\n\nimport std/text\n\n/// The JSON text for `value`, written from the record and sum types it is built out of.\nencode(value: a) -> str\n\n/// `text` read into the type the binding declares, failing with the field that did not match.\ndecode(text: str) -> a\n\n/// A JSON string literal, with the five escapes the format requires.\nquote(s: str) -> str =>\n    \"\\\"\" ++ s.replace(\"\\\\\", \"\\\\\\\\\")\n             .replace(\"\\\"\", \"\\\\\\\"\")\n             .replace(\"\\n\", \"\\\\n\")\n             .replace(\"\\r\", \"\\\\r\")\n             .replace(\"\\t\", \"\\\\t\") ++ \"\\\"\"\n\n/// `[\"a\", \"b\"]` from a `str[]`.\narray_of_str(xs: str[]) -> str =>\n    \"[\" ++ xs.map(quote).join(\",\") ++ \"]\"\n\n/// `[1, 2]` from an `int[]`.\narray_of_int(xs: int[]) -> str =>\n    \"[\" ++ xs.map(v => str(v)).join(\",\") ++ \"]\"\n\n/// `{\"k\":v}` from parallel key and (already-encoded) value lists.\nobject_of(keys: str[], values: str[]) -> str =>\n    \"\\{\" ++ pairs(keys, values, 0, []).join(\",\") ++ \"\\}\"\n\npairs(ks: str[], vs: str[], i: int, acc: str[]) -> str[] {\n    if i >= ks.length() || i >= vs.length() {\n        acc\n    } else {\n        pair = quote(ks.get(i)) ++ \":\" ++ vs.get(i)\n        pairs(ks, vs, i + 1, acc.push(pair))\n    }\n}\n\n/// The raw text of `key`'s value in a JSON object, or \"\" when it isn't there.\nget(src: str, key: str) -> str {\n    marker = quote(key) ++ \":\"\n    at = src.index_of(marker)\n\n    if at < 0 {\n        \"\"\n    } else {\n        value_at(src, at + marker.length())\n    }\n}\n\n/// `get`, parsed as an integer, with `dflt` when the key is absent.\nget_int(src: str, key: str, dflt: int) -> int {\n    v = get(src, key)\n\n    if v == \"\" {\n        dflt\n    } else {\n        int(v)\n    }\n}\n\n/// `get`, read as a boolean.\nget_bool(src: str, key: str) -> bool =>\n    get(src, key) == \"true\"\n\n/// The elements of a JSON array, each as raw text (strings unquoted).\nitems(src: str) -> str[] {\n    body = src.trim()\n\n    if !body.starts_with(\"[\") {\n        []\n    } else {\n        split_items(body.slice(1, body.length() - 1).chars(), 0, 0, \"\", [])\n    }\n}\n\nsplit_items(cs: str[], i: int, depth: int, cur: str, acc: str[]) -> str[] {\n    if i < cs.length() {\n        next_item(cs, i, depth, cur, acc)\n    } else if cur.trim() == \"\" {\n        acc\n    } else {\n        acc.push(unwrap(cur))\n    }\n}\n\nnext_item(cs: str[], i: int, depth: int, cur: str, acc: str[]) -> str[] {\n    c = cs.get(i)\n\n    if c == \"\\\"\" {\n        copy_string(cs, i + 1, depth, cur ++ c, acc)\n    } else if c == \",\" && depth == 0 {\n        split_items(cs, i + 1, depth, \"\", acc.push(unwrap(cur)))\n    } else {\n        split_items(cs, i + 1, depth + nesting(c), cur ++ c, acc)\n    }\n}\n\nnesting(c: str) -> int {\n    if c == \"[\" || c == \"\\{\" {\n        1\n    } else if c == \"]\" || c == \"\\}\" {\n        -1\n    } else {\n        0\n    }\n}\n\ncopy_string(cs: str[], i: int, depth: int, cur: str, acc: str[]) -> str[] {\n    if i >= cs.length() {\n        split_items(cs, i, depth, cur, acc)\n    } else if cs.get(i) == \"\\\\\" {\n        split_items_after_escape(cs, i, depth, cur, acc)\n    } else if cs.get(i) == \"\\\"\" {\n        split_items(cs, i + 1, depth, cur ++ \"\\\"\", acc)\n    } else {\n        copy_string(cs, i + 1, depth, cur ++ cs.get(i), acc)\n    }\n}\n\nsplit_items_after_escape(cs: str[], i: int, depth: int, cur: str,\n                         acc: str[]) -> str[] {\n    escaped = if i + 1 < cs.length() { cs.get(i + 1) } else { \"\" }\n\n    copy_string(cs, i + 2, depth, cur ++ cs.get(i) ++ escaped, acc)\n}\n\nvalue_at(src: str, at: int) -> str {\n    rest = src.slice(at, src.length()).trim()\n\n    if rest.starts_with(\"\\\"\") {\n        unescape(rest.slice(1, json_quote_end(rest.chars(), 1)))\n    } else if rest.starts_with(\"[\") || rest.starts_with(\"\\{\") {\n        rest.slice(0, balanced_end(rest.chars(), 0, 0))\n    } else {\n        rest.slice(0, bare_end(rest.chars(), 0))\n    }\n}\n\nbalanced_end(cs: str[], i: int, depth: int) -> int {\n    if i >= cs.length() {\n        i\n    } else {\n        balanced_step(cs, i, depth)\n    }\n}\n\nbalanced_step(cs: str[], i: int, depth: int) -> int {\n    c = cs.get(i)\n\n    if c == \"\\\"\" {\n        balanced_end(cs, skip_string(cs, i + 1), depth)\n    } else if c == \"[\" || c == \"\\{\" {\n        balanced_end(cs, i + 1, depth + 1)\n    } else if c != \"]\" && c != \"\\}\" {\n        balanced_end(cs, i + 1, depth)\n    } else if depth <= 1 {\n        i + 1\n    } else {\n        balanced_end(cs, i + 1, depth - 1)\n    }\n}\n\nskip_string(cs: str[], i: int) -> int {\n    end = json_quote_end(cs, i)\n\n    end >= cs.length() ? cs.length() : end + 1\n}\n\njson_quote_end(cs: str[], i: int) -> int {\n    if i >= cs.length() {\n        cs.length()\n    } else if cs.get(i) == \"\\\\\" {\n        json_quote_end(cs, i + 2)\n    } else if cs.get(i) == \"\\\"\" {\n        i\n    } else {\n        json_quote_end(cs, i + 1)\n    }\n}\n\nbare_end(cs: str[], i: int) -> int {\n    if i >= cs.length() {\n        i\n    } else if cs.get(i) == \",\" || cs.get(i) == \"\\}\" || cs.get(i) == \"]\" {\n        i\n    } else {\n        bare_end(cs, i + 1)\n    }\n}\n\nunwrap(s: str) -> str {\n    t = s.trim()\n\n    if t.length() >= 2 && t.starts_with(\"\\\"\") && t.ends_with(\"\\\"\") {\n        unescape(t.slice(1, t.length() - 1))\n    } else {\n        t\n    }\n}\n\nunescape(s: str) -> str =>\n    s.replace(\"\\\\n\", \"\\n\")\n     .replace(\"\\\\r\", \"\\r\")\n     .replace(\"\\\\t\", \"\\t\")\n     .replace(\"\\\\\\\"\", \"\\\"\")\n     .replace(\"\\\\\\\\\", \"\\\\\")\n"; maca_write_file(maca_cat(maca_cat("", root), "/std/json.maca"), std_json); const char* std_list = "// std/list: the list operations that aren't builtins.\n\n/// Does any element satisfy `pred`?\nany_of(xs: int[], pred) -> bool =>\n    scan_any(xs, 0, pred)\n\nscan_any(xs: int[], i: int, pred) -> bool {\n    if i >= xs.length() {\n        false\n    } else if pred(xs.get(i)) {\n        true\n    } else {\n        scan_any(xs, i + 1, pred)\n    }\n}\n\n/// Does every element satisfy `pred`?\nall_of(xs: int[], pred) -> bool =>\n    scan_all(xs, 0, pred)\n\nscan_all(xs: int[], i: int, pred) -> bool {\n    if i >= xs.length() {\n        true\n    } else if !pred(xs.get(i)) {\n        false\n    } else {\n        scan_all(xs, i + 1, pred)\n    }\n}\n\n/// The index of the first element satisfying `pred`, or -1.\nfind_index(xs: int[], pred) -> int =>\n    scan_find(xs, 0, pred)\n\nscan_find(xs: int[], i: int, pred) -> int {\n    if i >= xs.length() {\n        -1\n    } else if pred(xs.get(i)) {\n        i\n    } else {\n        scan_find(xs, i + 1, pred)\n    }\n}\n\n/// How many elements satisfy `pred`.\ncount_if(xs: int[], pred) -> int =>\n    xs.filter(pred).length()\n\n/// The first `n` elements.\ntake(xs: int[], n: int) -> int[] =>\n    xs.slice(0, clamp(n, xs.length()))\n\n/// Everything after the first `n` elements: the other half of `take`, and clamping the same way.\ndrop(xs: int[], n: int) -> int[] =>\n    xs.slice(clamp(n, xs.length()), xs.length())\n\nclamp(n: int, len: int) -> int {\n    if n < 0 {\n        0\n    } else if n > len {\n        len\n    } else {\n        n\n    }\n}\n\n/// Fixed-size groups, the last one short if the length doesn't divide.\nchunk(xs: int[], size: int) -> int[][] {\n    if size <= 0 {\n        []\n    } else {\n        chunk_from(xs, 0, size, [])\n    }\n}\n\nchunk_from(xs: int[], at: int, size: int, acc: int[][]) -> int[][] {\n    if at >= xs.length() {\n        acc\n    } else {\n        group = xs.slice(at, clamp(at + size, xs.length()))\n        chunk_from(xs, at + size, size, acc.push(group))\n    }\n}\n\n/// One list of the pairwise sums, stopping at the shorter input.\nzip_add(a: int[], b: int[]) -> int[] =>\n    zip_add_from(a, b, 0, [])\n\nzip_add_from(a: int[], b: int[], i: int, acc: int[]) -> int[] {\n    if i >= a.length() || i >= b.length() {\n        acc\n    } else {\n        zip_add_from(a, b, i + 1, acc.push(a.get(i) + b.get(i)))\n    }\n}\n\n/// Flatten one level.\nflatten(xss: int[][]) -> int[] =>\n    flatten_from(xss, 0, [])\n\nflatten_from(xss: int[][], i: int, acc: int[]) -> int[] {\n    if i >= xss.length() {\n        acc\n    } else {\n        flatten_from(xss, i + 1, acc ++ xss.get(i))\n    }\n}\n\n/// Values in first-seen order, duplicates dropped.\nunique(xs: int[]) -> int[] =>\n    unique_from(xs, 0, [])\n\nunique_from(xs: int[], i: int, acc: int[]) -> int[] {\n    if i >= xs.length() {\n        acc\n    } else if acc.contains(xs.get(i)) {\n        unique_from(xs, i + 1, acc)\n    } else {\n        unique_from(xs, i + 1, acc.push(xs.get(i)))\n    }\n}\n\n/// `[lo, lo+1, …, hi]`, empty when `hi < lo`.\nrange(lo: int, hi: int) -> int[] {\n    if hi < lo {\n        []\n    } else {\n        range_from(lo, hi, [])\n    }\n}\n\nrange_from(at: int, hi: int, acc: int[]) -> int[] {\n    if at > hi {\n        acc\n    } else {\n        range_from(at + 1, hi, acc.push(at))\n    }\n}\n\n/// `unique` for a `str[]`.\nstr_unique(xs: str[]) -> str[] =>\n    str_unique_from(xs, 0, [])\n\nstr_unique_from(xs: str[], i: int, acc: str[]) -> str[] {\n    if i >= xs.length() {\n        acc\n    } else if acc.contains(xs.get(i)) {\n        str_unique_from(xs, i + 1, acc)\n    } else {\n        str_unique_from(xs, i + 1, acc.push(xs.get(i)))\n    }\n}\n\n/// `take` for a `str[]`.\nstr_take(xs: str[], n: int) -> str[] =>\n    xs.slice(0, clamp(n, xs.length()))\n\n/// `drop` for a `str[]`.\nstr_drop(xs: str[], n: int) -> str[] =>\n    xs.slice(clamp(n, xs.length()), xs.length())\n\n/// `find_index` for a `str[]`.\nstr_find_index(xs: str[], pred) -> int =>\n    str_scan_find(xs, 0, pred)\n\nstr_scan_find(xs: str[], i: int, pred) -> int {\n    if i >= xs.length() {\n        -1\n    } else if pred(xs.get(i)) {\n        i\n    } else {\n        str_scan_find(xs, i + 1, pred)\n    }\n}\n\n/// `flatten` for a `str[][]`.\nstr_flatten(xss: str[][]) -> str[] =>\n    str_flatten_from(xss, 0, [])\n\nstr_flatten_from(xss: str[][], i: int, acc: str[]) -> str[] {\n    if i >= xss.length() {\n        acc\n    } else {\n        str_flatten_from(xss, i + 1, acc ++ xss.get(i))\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/std/list.maca"), std_list); const char* std_path = "// std/path: filesystem paths as strings, handled the way a build tool needs.\n\n/// Join two segments with exactly one separator, whatever each side brought.\njoin(a: str, b: str) -> str {\n    left = drop_trailing_sep(a)\n    right = drop_leading_sep(b)\n\n    if left == \"\" {\n        right\n    } else if right == \"\" {\n        left\n    } else {\n        left ++ \"/\" ++ right\n    }\n}\n\ndrop_trailing_sep(s: str) -> str {\n    if s.ends_with(\"/\") {\n        s.slice(0, s.length() - 1)\n    } else {\n        s\n    }\n}\n\ndrop_leading_sep(s: str) -> str {\n    if s.starts_with(\"/\") {\n        s.slice(1, s.length())\n    } else {\n        s\n    }\n}\n\n/// Everything after the last separator.\nbasename(p: str) -> str {\n    at = last_sep(p)\n\n    if at < 0 {\n        p\n    } else {\n        p.slice(at + 1, p.length())\n    }\n}\n\n/// Everything before the last separator.\ndirname(p: str) -> str {\n    at = last_sep(p)\n\n    if at < 0 {\n        \".\"\n    } else if at == 0 {\n        \"/\"\n    } else {\n        p.slice(0, at)\n    }\n}\n\n/// The extension without its dot, or \"\".\nextension(p: str) -> str {\n    name = basename(p)\n    at = last_dot(name)\n\n    if at <= 0 {\n        \"\"\n    } else {\n        name.slice(at + 1, name.length())\n    }\n}\n\n/// The basename with its extension removed.\nstem(p: str) -> str {\n    name = basename(p)\n    at = last_dot(name)\n\n    if at <= 0 {\n        name\n    } else {\n        name.slice(0, at)\n    }\n}\n\n/// Replace the extension (with or without a leading dot on `ext`).\nwith_extension(p: str, ext: str) -> str {\n    bare_ext = drop_leading_dot(ext)\n    dir = dirname(p)\n\n    name = if bare_ext == \"\" {\n        stem(p)\n    } else {\n        stem(p) ++ \".\" ++ bare_ext\n    }\n\n    if dir == \".\" && !p.starts_with(\"./\") {\n        name\n    } else {\n        join(dir, name)\n    }\n}\n\ndrop_leading_dot(ext: str) -> str {\n    if ext.starts_with(\".\") {\n        ext.slice(1, ext.length())\n    } else {\n        ext\n    }\n}\n\n/// Does `p` start from the root?\nis_absolute(p: str) -> bool =>\n    p.starts_with(\"/\")\n\n/// Collapse `.` and `..` segments textually.\nnormalize(p: str) -> str {\n    kept = walk_segments(p.split(\"/\"), 0, []).join(\"/\")\n\n    if is_absolute(p) {\n        \"/\" ++ kept\n    } else if kept == \"\" {\n        \".\"\n    } else {\n        kept\n    }\n}\n\nwalk_segments(segs: str[], i: int, acc: str[]) -> str[] {\n    if i >= segs.length() {\n        acc\n    } else {\n        walk_segments(segs, i + 1, step(acc, segs.get(i)))\n    }\n}\n\nstep(acc: str[], seg: str) -> str[] {\n    if seg == \"\" || seg == \".\" {\n        acc\n    } else if seg != \"..\" {\n        acc.push(seg)\n    } else if acc.length() > 0 {\n        acc.pop()\n    } else {\n        acc\n    }\n}\n\nlast_sep(p: str) -> int =>\n    scan_back(p.chars(), p.length() - 1, \"/\")\n\nlast_dot(s: str) -> int =>\n    scan_back(s.chars(), s.length() - 1, \".\")\n\nscan_back(cs: str[], i: int, want: str) -> int {\n    if i < 0 {\n        -1\n    } else if cs.get(i) == want {\n        i\n    } else {\n        scan_back(cs, i - 1, want)\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/std/path.maca"), std_path); const char* std_proc = "// std/proc: running other programs, for the scripts a project needs.\n\nimport std/path\n\n/// Run `cmd`, and stop the whole program if it fails.\nrun(cmd: str, args: str[]) -> bool {\n    code = exec(cmd, args)\n\n    if code == 0 {\n        true\n    } else {\n        fail \"{cmd} exited {code}\"\n    }\n}\n\n/// Run `cmd` and report whether it succeeded, without stopping.\ntry_run(cmd: str, args: str[]) -> bool =>\n    exec(cmd, args) == 0\n\n/// Run `cmd` with `dir` as the working directory, then change back.\nrun_in(dir: str, cmd: str, args: str[]) -> bool {\n    back = cwd()\n\n    if !chdir(dir) {\n        fail \"no such directory: {dir}\"\n    } else {\n        code = exec(cmd, args)\n        chdir(back)\n\n        if code == 0 {\n            true\n        } else {\n            fail \"{cmd} in {dir} exited {code}\"\n        }\n    }\n}\n\n/// The trimmed stdout of `cmd`.\noutput(cmd: str, args: str[]) -> str =>\n    capture(cmd, args).trim()\n\n/// Where `cmd` lives on PATH, or \"\".\nwhich(cmd: str) -> str {\n    if cmd.contains(\"/\") {\n        found_or_empty(cmd)\n    } else {\n        search_path(env(\"PATH\").split(\":\"), 0, cmd)\n    }\n}\n\n/// Is `cmd` on PATH at all?\nhave(cmd: str) -> bool =>\n    which(cmd) != \"\"\n\nsearch_path(dirs: str[], i: int, cmd: str) -> str {\n    if i >= dirs.length() {\n        \"\"\n    } else {\n        hit = found_or_empty(join(dirs.get(i), cmd))\n        if hit != \"\" {\n            hit\n        } else {\n            search_path(dirs, i + 1, cmd)\n        }\n    }\n}\n\nfound_or_empty(p: str) -> str {\n    if file_exists(p) && !is_dir(p) {\n        p\n    } else {\n        \"\"\n    }\n}\n\n/// An environment variable, or `dflt` when it is unset or empty.\nenv_or(name: str, dflt: str) -> str {\n    v = env(name)\n\n    if v == \"\" {\n        dflt\n    } else {\n        v\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/std/proc.maca"), std_proc); const char* std_text = "// std/text: string work that sits one level above the `str` builtins.\n\n/// The lines of `s`, without their terminators.\nlines(s: str) -> str[] {\n    parts = s.replace(\"\\r\\n\", \"\\n\").split(\"\\n\")\n    n = parts.length()\n\n    if n > 0 && parts.get(n - 1) == \"\" {\n        parts.slice(0, n - 1)\n    } else {\n        parts\n    }\n}\n\n/// Whitespace-separated words, with empty runs dropped.\nwords(s: str) -> str[] =>\n    keep_nonempty(s.replace(\"\\t\", \" \").replace(\"\\n\", \" \").split(\" \"), 0, [])\n\nkeep_nonempty(xs: str[], i: int, acc: str[]) -> str[] {\n    if i >= xs.length() {\n        acc\n    } else if xs.get(i) == \"\" {\n        keep_nonempty(xs, i + 1, acc)\n    } else {\n        keep_nonempty(xs, i + 1, acc.push(xs.get(i)))\n    }\n}\n\n/// Split on the *first* occurrence only: `split_once(\"a=b=c\", \"=\")` is `[\"a\", \"b=c\"]`.\nsplit_once(s: str, sep: str) -> str[] {\n    at = s.index_of(sep)\n\n    if at < 0 {\n        [s, \"\"]\n    } else {\n        [s.slice(0, at), s.slice(at + sep.length(), s.length())]\n    }\n}\n\n/// Remove `p` from the front, or leave `s` alone.\nstrip_prefix(s: str, p: str) -> str {\n    if s.starts_with(p) {\n        s.slice(p.length(), s.length())\n    } else {\n        s\n    }\n}\n\n/// Remove `p` from the end, or leave `s` alone.\nstrip_suffix(s: str, p: str) -> str {\n    if s.ends_with(p) {\n        s.slice(0, s.length() - p.length())\n    } else {\n        s\n    }\n}\n\n/// `index_of` starting from `start`, as an absolute index, or -1.\nindex_of_from(s: str, pat: str, start: int) -> int {\n    at = if start < 0 { 0 } else { start }\n\n    if at >= s.length() {\n        -1\n    } else {\n        hit = s.slice(at, s.length()).index_of(pat)\n\n        if hit < 0 {\n            -1\n        } else {\n            at + hit\n        }\n    }\n}\n\n/// The index of the *last* occurrence of `pat`, or -1.\nlast_index_of(s: str, pat: str) -> int =>\n    scan_last(s, pat, 0, -1)\n\nscan_last(s: str, pat: str, at: int, best: int) -> int {\n    hit = index_of_from(s, pat, at)\n\n    if hit < 0 {\n        best\n    } else {\n        scan_last(s, pat, hit + 1, hit)\n    }\n}\n\n/// The text between `open` and `close`, or \"\" if either marker is missing.\nbetween(s: str, open: str, close: str) -> str {\n    at = s.index_of(open)\n\n    if at < 0 {\n        \"\"\n    } else {\n        tail = s.slice(at + open.length(), s.length())\n        end = tail.index_of(close)\n\n        if end < 0 {\n            \"\"\n        } else {\n            tail.slice(0, end)\n        }\n    }\n}\n\n/// The four characters that would otherwise be markup, as entities.\nescape_html(s: str) -> str =>\n    s.replace(\"&\", \"&amp;\")\n        .replace(\"<\", \"&lt;\")\n        .replace(\">\", \"&gt;\")\n        .replace(\"\\\"\", \"&quot;\")\n\n/// How many non-overlapping times `pat` occurs in `s`.\ncount(s: str, pat: str) -> int {\n    if pat.length() == 0 {\n        0\n    } else {\n        count_from(s, pat, 0, 0)\n    }\n}\n\ncount_from(s: str, pat: str, at: int, n: int) -> int {\n    hit = s.slice(at, s.length()).index_of(pat)\n\n    if hit < 0 {\n        n\n    } else {\n        count_from(s, pat, at + hit + pat.length(), n + 1)\n    }\n}\n\n/// `Title Case`, one word at a time.\ntitle_case(s: str) -> str =>\n    join_words(words(s).map(capitalize), 0, \"\")\n\ncapitalize(w: str) -> str {\n    if w.length() == 0 {\n        w\n    } else {\n        w.at(0).upper() ++ w.slice(1, w.length()).lower()\n    }\n}\n\njoin_words(ws: str[], i: int, acc: str) -> str {\n    if i >= ws.length() {\n        acc\n    } else if acc == \"\" {\n        join_words(ws, i + 1, ws.get(i))\n    } else {\n        join_words(ws, i + 1, acc ++ \" \" ++ ws.get(i))\n    }\n}\n\n/// Add `pad` to the start of every line.\nindent(s: str, pad: str) -> str =>\n    lines(s).map(l => pad_unless_empty(l, pad)).join(\"\\n\")\n\npad_unless_empty(line: str, pad: str) -> str {\n    if line == \"\" {\n        line\n    } else {\n        pad ++ line\n    }\n}\n\n/// Remove the longest run of leading spaces common to every non-empty line.\ndedent(s: str) -> str {\n    cut = common_indent(lines(s), 0, -1)\n\n    if cut <= 0 {\n        s\n    } else {\n        lines(s).map(l => drop_indent(l, cut)).join(\"\\n\")\n    }\n}\n\ndrop_indent(line: str, cut: int) -> str {\n    if line.length() >= cut {\n        line.slice(cut, line.length())\n    } else {\n        line\n    }\n}\n\ncommon_indent(ls: str[], i: int, best: int) -> int {\n    if i < ls.length() {\n        common_indent(ls, i + 1, narrower(best, ls.get(i)))\n    } else if best < 0 {\n        0\n    } else {\n        best\n    }\n}\n\nnarrower(best: int, line: str) -> int {\n    n = leading_spaces(line.chars(), 0)\n\n    if line.trim() == \"\" {\n        best\n    } else if best < 0 || n < best {\n        n\n    } else {\n        best\n    }\n}\n\nleading_spaces(cs: str[], i: int) -> int {\n    if i >= cs.length() || cs.get(i) != \" \" {\n        i\n    } else {\n        leading_spaces(cs, i + 1)\n    }\n}\n\n/// Fold `s` to lines of at most `width` bytes, breaking between words.\nwrap(s: str, width: int) -> str =>\n    fill(words(s), 0, width, \"\", \"\")\n\nfill(ws: str[], i: int, width: int, cur: str, out: str) -> str {\n    if i >= ws.length() {\n        flush(out, cur)\n    } else {\n        next_word(ws, i, width, cur, out)\n    }\n}\n\nnext_word(ws: str[], i: int, width: int, cur: str, out: str) -> str {\n    w = ws.get(i)\n    joined = if cur == \"\" { w } else { cur ++ \" \" ++ w }\n\n    if joined.length() <= width || cur == \"\" {\n        fill(ws, i + 1, width, joined, out)\n    } else {\n        fill(ws, i + 1, width, w, flush(out, cur))\n    }\n}\n\nflush(out: str, cur: str) -> str {\n    if cur == \"\" {\n        out\n    } else if out == \"\" {\n        cur\n    } else {\n        out ++ \"\\n\" ++ cur\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/std/text.maca"), std_text); const char* cli_help = "import { Cmd, Opt } from cli/spec\nimport { bold, dim, grey, pad, width } from cli/style\n\n/// The whole help page for `c`.\nhelp(c: Cmd) -> str {\n    out = bold(c.name) ++ (c.about == \"\" ? \"\" : \": \" ++ c.about) ++ \"\\n\\n\"\n    out = out ++ bold(\"Usage\") ++ \"\\n  \" ++ usage(c) ++ \"\\n\"\n\n    if c.args.length() > 0 {\n        out = out ++ \"\\n\" ++ bold(\"Arguments\") ++ \"\\n\" ++ arg_lines(c, 0, \"\")\n    }\n    out ++ \"\\n\" ++ bold(\"Options\") ++ \"\\n\" ++ opt_lines(c, 0, \"\") ++ help_line(c)\n}\n\n/// The one line that shows how the command is invoked.\nusage(c: Cmd) -> str {\n    line = c.name\n    if c.opts.length() > 0 {\n        line = line ++ \" [options]\"\n    }\n    line ++ arg_usage(c, 0, \"\")\n}\n\narg_usage(c: Cmd, i: int, acc: str) -> str {\n    if i >= c.args.length() {\n        acc\n    } else {\n        a = c.args.get(i)\n        arg_usage(c, i + 1, acc ++ (a.many ? \" <{a.name}>...\" : \" <{a.name}>\"))\n    }\n}\n\ncolumn(c: Cmd) -> int {\n    w = 10\n    for a in c.args {\n        cw = width(\"<{a.name}>\")\n        if cw > w {\n            w = cw\n        }\n    }\n    for o in c.opts {\n        cw = width(left_of(o))\n        if cw > w {\n            w = cw\n        }\n    }\n    w + 2\n}\n\nleft_of(o: Opt) -> str =>\n    o.short == \"\" ? \"    --{o.long}\" : \"-{o.short}, --{o.long}\"\n\narg_lines(c: Cmd, i: int, acc: str) -> str {\n    if i >= c.args.length() {\n        acc\n    } else {\n        a = c.args.get(i)\n        arg_lines(c, i + 1, acc ++ \"  \" ++ pad(\"<{a.name}>\", column(c)) ++ a.help ++ \"\\n\")\n    }\n}\n\nopt_lines(c: Cmd, i: int, acc: str) -> str {\n    if i >= c.opts.length() {\n        acc\n    } else {\n        o = c.opts.get(i)\n        tail = o.takes && o.fallback != \"\" ? grey(\"  (default: {o.fallback})\") : \"\"\n        line = \"  \" ++ pad(left_of(o), column(c)) ++ o.help ++ tail\n        opt_lines(c, i + 1, acc ++ line ++ \"\\n\")\n    }\n}\n\nhelp_line(c: Cmd) -> str =>\n    \"  \" ++ pad(\"-h, --help\", column(c)) ++ dim(\"show this and exit\") ++ \"\\n\"\n"; maca_write_file(maca_cat(maca_cat("", root), "/cli/help.maca"), cli_help); const char* cli_parse = "import { find_long, find_short, found, long_names } from cli/spec\n\nParsed = {\n    /// Every option given, by long name.\n    opts: Map str str,\n    /// The positionals, in order.\n    args: str[],\n    /// Empty when the line was understood.\n    error: str,\n    /// Was `--help` or `-h` asked for?\n    wants_help: bool,\n}\n\n/// Read `argv` against `c`.\nparse(c: Cmd, argv: str[]) -> Parsed {\n    empty: Map str str = map()\n    out = Parsed { opts = empty, args = [], error = \"\", wants_help = false }\n    n = argv.length()\n    i = 0\n    only_args = false\n\n    while i < n {\n        a = argv.get(i)\n\n        if only_args {\n            out = out with { args = out.args.push(a) }\n            i = i + 1\n        } else if a == \"--\" {\n            only_args = true\n            i = i + 1\n        } else if a == \"--help\" || a == \"-h\" {\n            out = out with { wants_help = true }\n            i = i + 1\n        } else if a.starts_with(\"--\") {\n            step = take_long(c, out, a.substr(2, a.length() - 2), argv, i)\n            out = step.parsed\n            i = step.next\n        } else if a.starts_with(\"-\") && a != \"-\" {\n            step = take_short(c, out, a.substr(1, a.length() - 1), argv, i)\n            out = step.parsed\n            i = step.next\n        } else {\n            out = out with { args = out.args.push(a) }\n            i = i + 1\n        }\n\n        if out.error != \"\" {\n            i = n\n        }\n    }\n\n    out.error != \"\" || out.wants_help ? out : check_args(c, out)\n}\n\nStep = { parsed: Parsed, next: int }\n\nrefuse(p: Parsed, why: str, i: int) -> Step =>\n    Step { parsed = p with { error = why }, next = i + 1 }\n\ntake_long(c: Cmd, p: Parsed, body: str, argv: str[], i: int) -> Step {\n    cut = body.index_of(\"=\")\n    name = cut >= 0 ? body.substr(0, cut) : body\n    inline = cut >= 0 ? body.substr(cut + 1, body.length() - cut - 1) : \"\"\n    o = find_long(c, name)\n\n    if !found(o) {\n        refuse(p, unknown(c, \"--\" ++ name), i)\n    } else if !o.takes {\n        if cut >= 0 {\n            why = \"`--{name}` is a flag and takes no value\"\n            refuse(p, why ++ \". Write `--{name}` on its own\", i)\n        } else {\n            Step { parsed = set(p, name, \"true\"), next = i + 1 }\n        }\n    } else if cut >= 0 {\n        Step { parsed = set(p, name, inline), next = i + 1 }\n    } else if i + 1 < argv.length() {\n        Step { parsed = set(p, name, argv.get(i + 1)), next = i + 2 }\n    } else {\n        refuse(p, needs_value(\"--\" ++ name, o.help), i)\n    }\n}\n\ntake_short(c: Cmd, p: Parsed, body: str, argv: str[], i: int) -> Step {\n    cut = body.index_of(\"=\")\n    name = cut >= 0 ? body.substr(0, cut) : body.substr(0, 1)\n    inline = cut >= 0 ? body.substr(cut + 1, body.length() - cut - 1) : \"\"\n    o = find_short(c, name)\n\n    if !found(o) {\n        refuse(p, unknown(c, \"-\" ++ name), i)\n    } else if o.takes && cut >= 0 {\n        Step { parsed = set(p, o.long, inline), next = i + 1 }\n    } else if o.takes && body.length() > 1 {\n        why = \"`-{name}` takes a value\"\n        refuse(p, why ++ \". Write `-{name} <value>` or `-{name}=<value>`\", i)\n    } else if o.takes {\n        if i + 1 < argv.length() {\n            Step { parsed = set(p, o.long, argv.get(i + 1)), next = i + 2 }\n        } else {\n            refuse(p, needs_value(\"-\" ++ name, o.help), i)\n        }\n    } else {\n        Step { parsed = bundle(c, p, body, 0), next = i + 1 }\n    }\n}\n\nbundle(c: Cmd, p: Parsed, body: str, at: int) -> Parsed {\n    if at >= body.length() || p.error != \"\" {\n        p\n    } else {\n        s = body.at(at)\n        o = find_short(c, s)\n\n        if !found(o) {\n            p with { error = unknown(c, \"-\" ++ s) }\n        } else if o.takes {\n            bundle(c, p with {\n                error = \"`-{s}` takes a value, so it cannot be bundled. Write it on its own\"\n            }, body, at + 1)\n        } else {\n            bundle(c, set(p, o.long, \"true\"), body, at + 1)\n        }\n    }\n}\n\nset(p: Parsed, name: str, value: str) -> Parsed =>\n    p with { opts = p.opts.set(name, value) }\n\nunknown(c: Cmd, given: str) -> str {\n    near = nearest(given.replace(\"-\", \"\"), long_names(c), 0, \"\", 3)\n    near == \"\"\n        ? \"unknown option `{given}`\"\n        : \"unknown option `{given}`: did you mean `--{near}`?\"\n}\n\nneeds_value(given: str, what: str) -> str =>\n    what == \"\"\n        ? \"`{given}` needs a value\"\n        : \"`{given}` needs a value: {what}\"\n\nnearest(want: str, names: str[], i: int, found: str, best: int) -> str {\n    if i >= names.length() {\n        found\n    } else {\n        d = distance(want, names.get(i))\n        d < best\n            ? nearest(want, names, i + 1, names.get(i), d)\n            : nearest(want, names, i + 1, found, best)\n    }\n}\n\ndistance(a: str, b: str) -> int {\n    prev = row(b.length() + 1, 0, [])\n    i = 0\n    while i < a.length() {\n        cur = [i + 1]\n        j = 0\n        while j < b.length() {\n            cost = a.at(i) == b.at(j) ? 0 : 1\n            sub = prev.get(j) + cost\n            best = least(sub, prev.get(j + 1) + 1, cur.get(j) + 1)\n            cur = cur.push(best)\n            j = j + 1\n        }\n        prev = cur\n        i = i + 1\n    }\n    prev.get(b.length())\n}\n\nrow(n: int, at: int, acc: int[]) -> int[] =>\n    at >= n ? acc : row(n, at + 1, acc.push(at))\n\nleast(a: int, b: int, c: int) -> int {\n    m = a < b ? a : b\n    m < c ? m : c\n}\n\ncheck_args(c: Cmd, p: Parsed) -> Parsed {\n    want = c.args.length()\n    got = p.args.length()\n    takes_rest = want > 0 && c.args.get(want - 1).many\n\n    if got < want && !(takes_rest && got >= want - 1) {\n        p with { error = \"missing <{c.args.get(got).name}>: {c.args.get(got).help}\" }\n    } else if got > want && !takes_rest {\n        p with {\n            error = \"too many arguments: `{p.args.get(want)}`. {c.name} takes {want}\"\n        }\n    } else {\n        name_args(c, p, 0)\n    }\n}\n\nname_args(c: Cmd, p: Parsed, i: int) -> Parsed {\n    if i >= c.args.length() || i >= p.args.length() {\n        p\n    } else if c.args.get(i).many {\n        set(p, c.args.get(i).name, p.args.slice(i, p.args.length()).join(\" \"))\n    } else {\n        name_args(c, set(p, c.args.get(i).name, p.args.get(i)), i + 1)\n    }\n}\n\n/// The value given for `name`, or `fallback`.\nvalue(p: Parsed, name: str, fallback: str) -> str => p.opts.get(name, fallback)\n\n/// Whether a flag was given.\non(p: Parsed, name: str) -> bool => p.opts.get(name, \"\") == \"true\"\n\n/// A numeric option, or `fallback` when it was not given.\ncount(p: Parsed, name: str, fallback: int) -> int {\n    v = p.opts.get(name, \"\")\n    v == \"\" ? fallback : int(v)\n}\n\n/// The positional at `i`, or \"\" past the end.\nat(p: Parsed, i: int) -> str => p.args.get(i)\n\n/// Everything from `i` on: what a trailing `rest` argument collects.\nfrom(p: Parsed, i: int) -> str[] => p.args.slice(i, p.args.length())\n"; maca_write_file(maca_cat(maca_cat("", root), "/cli/parse.maca"), cli_parse); const char* cli_show = "import { bold, dim, grey, pad, pad_left, width } from cli/style\n\n/// A table with a header row, columns as wide as their widest cell.\ntable(header: str[], rows: str[][]) -> str {\n    cols = header.length()\n    w = widths(header, rows, cols)\n\n    out = \"\"\n    i = 0\n    while i < cols {\n        cell = bold(pad(header.get(i), w.get(i)))\n        out = out ++ cell ++ (i + 1 < cols ? \"  \" : \"\")\n        i = i + 1\n    }\n    out = out ++ \"\\n\"\n\n    i = 0\n    while i < cols {\n        out = out ++ grey(\"─\".repeat(w.get(i))) ++ (i + 1 < cols ? \"  \" : \"\")\n        i = i + 1\n    }\n    out = out ++ \"\\n\"\n\n    for row in rows {\n        out = out ++ row_text(row, w, cols) ++ \"\\n\"\n    }\n    out\n}\n\n/// The same table with the numeric columns right-aligned.\ntable_aligned(header: str[], rows: str[][]) -> str {\n    cols = header.length()\n    w = widths(header, rows, cols)\n\n    out = \"\"\n    i = 0\n    while i < cols {\n        head = numeric_column(rows, i) ? pad_left(header.get(i), w.get(i))\n                                      : pad(header.get(i), w.get(i))\n        out = out ++ bold(head) ++ (i + 1 < cols ? \"  \" : \"\")\n        i = i + 1\n    }\n    out = out ++ \"\\n\"\n\n    i = 0\n    while i < cols {\n        out = out ++ grey(\"─\".repeat(w.get(i))) ++ (i + 1 < cols ? \"  \" : \"\")\n        i = i + 1\n    }\n    out = out ++ \"\\n\"\n\n    for row in rows {\n        j = 0\n        line = \"\"\n        while j < cols {\n            cell = j < row.length() ? row.get(j) : \"\"\n            line = line ++ (numeric_column(rows, j) ? pad_left(cell, w.get(j))\n                                                    : pad(cell, w.get(j)))\n            line = line ++ (j + 1 < cols ? \"  \" : \"\")\n            j = j + 1\n        }\n        out = out ++ line ++ \"\\n\"\n    }\n    out\n}\n\nwidths(header: str[], rows: str[][], cols: int) -> int[] {\n    w = []\n    i = 0\n    while i < cols {\n        best = width(header.get(i))\n        for row in rows {\n            if i < row.length() && width(row.get(i)) > best {\n                best = width(row.get(i))\n            }\n        }\n        w = w.push(best)\n        i = i + 1\n    }\n    w\n}\n\nrow_text(row: str[], w: int[], cols: int) -> str {\n    out = \"\"\n    i = 0\n    while i < cols {\n        cell = i < row.length() ? row.get(i) : \"\"\n        out = out ++ pad(cell, w.get(i)) ++ (i + 1 < cols ? \"  \" : \"\")\n        i = i + 1\n    }\n    out\n}\n\nnumeric_column(rows: str[][], i: int) -> bool =>\n    filled(rows, i, 0) && all_numeric(rows, i, 0)\n\nfilled(rows: str[][], i: int, at: int) -> bool {\n    if at >= rows.length() {\n        false\n    } else if i < rows.get(at).length() && rows.get(at).get(i) != \"\" {\n        true\n    } else {\n        filled(rows, i, at + 1)\n    }\n}\n\nall_numeric(rows: str[][], i: int, at: int) -> bool {\n    if at >= rows.length() {\n        true\n    } else if i >= rows.get(at).length() || rows.get(at).get(i) == \"\" {\n        all_numeric(rows, i, at + 1)\n    } else if numeric(rows.get(at).get(i)) {\n        all_numeric(rows, i, at + 1)\n    } else {\n        false\n    }\n}\n\nnumeric(s: str) -> bool {\n    body = s.starts_with(\"-\") ? s.substr(1, s.length() - 1) : s\n    body != \"\" && digits_only(body, 0)\n}\n\ndigits_only(s: str, i: int) -> bool {\n    if i >= s.length() {\n        true\n    } else if s.at(i).is_ascii_digit() || s.at(i) == \".\" || s.at(i) == \",\" {\n        digits_only(s, i + 1)\n    } else {\n        false\n    }\n}\n\n/// A horizontal rule, optionally with a title sitting in it.\nrule(title: str) -> str {\n    w = 60\n    if title == \"\" {\n        grey(\"─\".repeat(w))\n    } else {\n        left = grey(\"── \")\n        right = w - width(title) - 4\n        left ++ bold(title) ++ \" \" ++ grey(\"─\".repeat(right > 0 ? right : 0))\n    }\n}\n\n/// A box around `body`, with `title` in its top edge.\npanel(title: str, body: str) -> str {\n    lines = body.split(\"\\n\")\n    inner = widest(lines, 0, width(title) + 2)\n\n    edge = \"─\".repeat(inner - width(title) - 1)\n    out = grey(\"┌─ \") ++ bold(title) ++ grey(\" \" ++ edge ++ \"┐\")\n    out = out ++ \"\\n\"\n    for line in lines {\n        out = out ++ grey(\"│ \") ++ pad(line, inner) ++ grey(\" │\") ++ \"\\n\"\n    }\n    out ++ grey(\"└\" ++ \"─\".repeat(inner + 2) ++ \"┘\")\n}\n\nwidest(lines: str[], i: int, best: int) -> int {\n    if i >= lines.length() {\n        best\n    } else if width(lines.get(i)) > best {\n        widest(lines, i + 1, width(lines.get(i)))\n    } else {\n        widest(lines, i + 1, best)\n    }\n}\n\n/// ` key value`: a labelled fact, with the label dimmed so the value is what the eye lands on.\nkv(key: str, value: str) -> str => \"  \" ++ dim(pad(key, 14)) ++ value\n\n/// A bulleted line.\nbullet(s: str) -> str => \"  \" ++ grey(\"•\") ++ \" \" ++ s\n\n/// `[####----] n%`: a progress bar of a given width.\nbar(done: int, total: int, w: int) -> str {\n    share = total > 0 ? done * w / total : 0\n    filled = share > w ? w : (share < 0 ? 0 : share)\n    pct = total > 0 ? done * 100 / total : 0\n    body = \"█\".repeat(filled) ++ grey(\"░\".repeat(w - filled))\n    \"[\" ++ body ++ \"] \" ++ pad_left(\"{pct}%\", 4)\n}\n\n/// The same line, rewritten in place: carriage return, no newline.\nredraw(s: str) {\n    if is_tty() {\n        print(\"\\r\" ++ s)\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/cli/show.maca"), cli_show); const char* cli_spec = "/// One `--name` the command accepts.\nOpt = {\n    long: str,\n    short: str,\n    help: str,\n    fallback: str,\n    takes: bool,\n}\n\n/// One positional.\nArg = {\n    name: str,\n    help: str,\n    many: bool,\n}\n\nCmd = {\n    name: str,\n    about: str,\n    opts: Opt[],\n    args: Arg[],\n}\n\n/// A command with a name and one line saying what it does.\ncommand(name: str, about: str) -> Cmd =>\n    Cmd { name = name, about = about, opts = [], args = [] }\n\n/// `--long value` / `-s value`, with `fallback` when it is not given.\nopt(c: Cmd, long: str, short: str, help: str, fallback: str) -> Cmd =>\n    c with {\n        opts = c.opts.push(Opt {\n            long = long,\n            short = short,\n            help = help,\n            fallback = fallback,\n            takes = true,\n        })\n    }\n\n/// `--long` / `-s`, present or absent.\nflag(c: Cmd, long: str, short: str, help: str) -> Cmd =>\n    c with {\n        opts = c.opts.push(Opt {\n            long = long,\n            short = short,\n            help = help,\n            fallback = \"\",\n            takes = false,\n        })\n    }\n\n/// One positional, in the order it is written.\narg(c: Cmd, name: str, help: str) -> Cmd => add_arg(c, name, help, false)\n\n/// A positional that takes the rest of the command line.\nrest(c: Cmd, name: str, help: str) -> Cmd => add_arg(c, name, help, true)\n\nadd_arg(c: Cmd, name: str, help: str, many: bool) -> Cmd =>\n    c with { args = c.args.push(Arg { name = name, help = help, many = many }) }\n\n/// The option `--<long>` names, or one with an empty `long` if there is none.\nfind_long(c: Cmd, long: str) -> Opt {\n    match_at(c.opts, 0, long, true)\n}\n\n/// The option `-<short>` names, or one with an empty `long` if there is none.\nfind_short(c: Cmd, short: str) -> Opt {\n    match_at(c.opts, 0, short, false)\n}\n\nmatch_at(opts: Opt[], i: int, want: str, by_long: bool) -> Opt {\n    if i >= opts.length() {\n        Opt { long = \"\", short = \"\", help = \"\", fallback = \"\", takes = false }\n    } else if by_long && opts.get(i).long == want {\n        opts.get(i)\n    } else if !by_long && want != \"\" && opts.get(i).short == want {\n        opts.get(i)\n    } else {\n        match_at(opts, i + 1, want, by_long)\n    }\n}\n\n/// Did a lookup find anything?\nfound(o: Opt) -> bool => o.long != \"\"\n\n/// The long names the command accepts, for a `did you mean` on a misspelling.\nlong_names(c: Cmd) -> str[] => names_from(c.opts, 0, [])\n\nnames_from(opts: Opt[], i: int, acc: str[]) -> str[] {\n    if i >= opts.length() {\n        acc\n    } else {\n        names_from(opts, i + 1, acc.push(opts.get(i).long))\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/cli/spec.maca"), cli_spec); const char* cli_style = "/// Should output carry escape codes right now?\nenabled() -> bool {\n    if env(\"NO_COLOR\") != \"\" {\n        false\n    } else if env(\"FORCE_COLOR\") != \"\" {\n        true\n    } else {\n        is_tty()\n    }\n}\n\n/// `s` wrapped in an SGR code, or `s` unchanged where colour is off.\npaint(code: str, s: str) -> str {\n    if !enabled() || s == \"\" {\n        s\n    } else {\n        chr(27) ++ \"[\" ++ code ++ \"m\" ++ s ++ chr(27) ++ \"[0m\"\n    }\n}\n\n/// How many columns `s` takes on screen.\nwidth(s: str) -> int {\n    n = s.length()\n    out = 0\n    i = 0\n    while i < n {\n        b = ord(s.at(i))\n        if b == 27 {\n            i = skip_escape(s, i + 1)\n        } else if b < 128 {\n            out = out + 1\n            i = i + 1\n        } else {\n            len = utf8_len(b)\n            out = out + columns(codepoint(s, i, len))\n            i = i + len\n        }\n    }\n    out\n}\n\nutf8_len(b: int) -> int {\n    if b >= 240 {\n        4\n    } else if b >= 224 {\n        3\n    } else if b >= 192 {\n        2\n    } else {\n        1\n    }\n}\n\ncodepoint(s: str, i: int, len: int) -> int {\n    lead = ord(s.at(i))\n    cp = lead - lead_base(len)\n    at = 1\n    while at < len {\n        cp = cp * 64 + tail(s, i + at)\n        at = at + 1\n    }\n    cp\n}\n\nlead_base(len: int) -> int {\n    if len == 4 {\n        240\n    } else if len == 3 {\n        224\n    } else if len == 2 {\n        192\n    } else {\n        0\n    }\n}\n\ntail(s: str, i: int) -> int {\n    b = ord(s.at(i))\n    b >= 128 ? b - 128 : 0\n}\n\ncolumns(cp: int) -> int {\n    if cp >= 768 && cp <= 879 {\n        0\n    } else if cp == 8203 {\n        0\n    } else if cp >= 4352 && cp <= 4447 {\n        2\n    } else if cp >= 11904 && cp <= 42191 {\n        2\n    } else if cp >= 44032 && cp <= 55203 {\n        2\n    } else if cp >= 63744 && cp <= 64255 {\n        2\n    } else if cp >= 65072 && cp <= 65135 {\n        2\n    } else if cp >= 65280 && cp <= 65376 {\n        2\n    } else if cp >= 127744 && cp <= 129791 {\n        2\n    } else {\n        1\n    }\n}\n\nskip_escape(s: str, from: int) -> int {\n    n = s.length()\n    i = from\n    while i < n && !s.at(i).is_alpha() {\n        i = i + 1\n    }\n    i + 1\n}\n\n/// Pad `s` to `w` columns, counting what shows rather than what is stored.\npad(s: str, w: int) -> str {\n    short = w - width(s)\n    short > 0 ? s ++ \" \".repeat(short) : s\n}\n\n/// Right-align `s` within `w` columns, for a column of numbers.\npad_left(s: str, w: int) -> str {\n    short = w - width(s)\n    short > 0 ? \" \".repeat(short) ++ s : s\n}\n\n/// Drop every escape sequence, leaving the text a file should get.\nplain(s: str) -> str {\n    n = s.length()\n    out = \"\"\n    i = 0\n    while i < n {\n        if s.at(i) == chr(27) {\n            i = skip_escape(s, i + 1)\n        } else {\n            out = out ++ s.at(i)\n            i = i + 1\n        }\n    }\n    out\n}\n\nbold(s: str) -> str => paint(\"1\", s)\ndim(s: str) -> str => paint(\"2\", s)\nitalic(s: str) -> str => paint(\"3\", s)\nunderline(s: str) -> str => paint(\"4\", s)\n\nred(s: str) -> str => paint(\"31\", s)\ngreen(s: str) -> str => paint(\"32\", s)\nyellow(s: str) -> str => paint(\"33\", s)\nblue(s: str) -> str => paint(\"34\", s)\nmagenta(s: str) -> str => paint(\"35\", s)\ncyan(s: str) -> str => paint(\"36\", s)\ngrey(s: str) -> str => paint(\"90\", s)\n\n/// The four things a command line says about what happened, each with the marker and colour it always has.\nok(s: str) -> str => green(\"✓\") ++ \" \" ++ s\nwarn(s: str) -> str => yellow(\"!\") ++ \" \" ++ s\nbad(s: str) -> str => red(\"✗\") ++ \" \" ++ s\nnote(s: str) -> str => grey(\"-\") ++ \" \" ++ grey(s)\n"; maca_write_file(maca_cat(maca_cat("", root), "/cli/style.maca"), cli_style); const char* web_file = "// web/file: handing a file to the reader, and taking one back.\n//\n// The name a download is offered under is decided here rather than by the\n// host, so `web/format`'s rule for it is the one every target agrees on.\n\nimport { safe_name } from web/format\n\n/// Offer `text` to the reader as a file called `name`.\ndownload(name: str, text: str) -> bool =>\n    browser_download(safe_name(name), text)\n\n/// The text of a file the reader picks among the kinds `accept` names, or \"\" if they pick none.\npick_text(accept: str) -> str\n\n/// Hand `text` to the browser under a name it has already been told is safe.\nbrowser_download(name: str, text: str) -> bool\n\nimport \"file.js\" \"\"\"\nmaca.provide({\n  browser_download: (name, text) => {\n    const blob = new Blob([text], { type: \"text/plain;charset=utf-8\" });\n    const url = URL.createObjectURL(blob);\n    const a = document.createElement(\"a\");\n    a.href = url;\n    a.download = name;\n    document.body.appendChild(a);\n    a.click();\n    a.remove();\n    URL.revokeObjectURL(url);\n    return true;\n  },\n  pick_text: (accept) =>\n    new Promise((settle) => {\n      const input = document.createElement(\"input\");\n      input.type = \"file\";\n      input.accept = accept;\n      input.addEventListener(\"cancel\", () => settle(\"\"));\n      input.addEventListener(\"change\", () => {\n        const file = input.files && input.files[0];\n        if (!file) return settle(\"\");\n        file.text().then(settle, () => settle(\"\"));\n      });\n      input.click();\n    }),\n});\n\"\"\"\n"; maca_write_file(maca_cat(maca_cat("", root), "/web/file.maca"), web_file); const char* web_format = "// web/format: the half of the browser modules that is arithmetic.\n//\n// Nothing here asks the host anything, so it reads the same on every target\n// and its answers are the ones `web/time` and `web/file` present.\n\n/// `n` written with at least two digits, which is what a clock reads.\ntwo(n: int) -> str => n < 10 && n >= 0 ? \"0{n}\" : \"{n}\"\n\n/// The hour and minute as a 24-hour clock reads them.\nclock(hour: int, minute: int) -> str => \"{two(hour)}:{two(minute)}\"\n\n/// The hour and minute as a 12-hour clock reads them, with the half of the day.\nclock12(hour: int, minute: int) -> str {\n    half = hour < 12 ? \"am\" : \"pm\"\n    h = hour % 12\n    shown = h == 0 ? 12 : h\n    \"{shown}:{two(minute)} {half}\"\n}\n\n/// The year, month and day as one sortable stamp.\nstamp(year: int, month: int, day: int) -> str =>\n    \"{year}-{two(month)}-{two(day)}\"\n\n/// `name` reduced to something every file system will accept, and never empty.\nsafe_name(name: str) -> str {\n    cs = name.trim().chars()\n    out = \"\"\n    for c in cs {\n        out = keeps(c) ? out ++ c : out ++ \"-\"\n    }\n    trimmed = trim_dashes(out)\n    trimmed == \"\" ? \"download\" : trimmed\n}\n\n/// Is this character one a file name keeps as it is?\nkeeps(c: str) -> bool =>\n    c.is_ascii_digit() || c.is_alpha() || c == \".\" || c == \"-\" || c == \"_\"\n\n/// `s` without the separators a name should not begin or end with.\ntrim_dashes(s: str) -> str {\n    lo = 0\n    hi = s.length()\n    while lo < hi && s.at(lo) == \"-\" {\n        lo = lo + 1\n    }\n    while hi > lo && s.at(hi - 1) == \"-\" {\n        hi = hi - 1\n    }\n    s.slice(lo, hi)\n}\n\n/// The storage key `name` belongs to under the program called `app`.\nslot(app: str, name: str) -> str => \"{app}.{name}\"\n"; maca_write_file(maca_cat(maca_cat("", root), "/web/format.maca"), web_format); const char* web_storage = "// web/storage: what the browser remembers between visits.\n//\n// `stored(key, default)` is the whole surface a program needs: the name starts\n// as whatever is saved under `key`, and assigning the name saves it again. The\n// three functions below are what that is written in terms of, and a program\n// that only wants the sugar never calls them.\n\n/// The value saved under `key`, or `fallback` when the browser has nothing there.\nlocal_start(key: str, fallback: a) -> a\n\n/// Save `value` under `key` and answer it, so assigning a stored name is the save.\nlocal_store(key: str, value: a) -> a\n\n/// Forget whatever is saved under `key`, so the next visit starts from the default again.\nlocal_forget(key: str) -> bool\n\nimport \"storage.js\" \"\"\"\nmaca.provide({\n  local_start: (key, fallback) => {\n    const store = globalThis.localStorage;\n    if (!store) return fallback;\n    const text = store.getItem(key);\n    if (text === null) return fallback;\n    try {\n      return JSON.parse(text);\n    } catch (e) {\n      return fallback;\n    }\n  },\n  local_store: (key, value) => {\n    const store = globalThis.localStorage;\n    if (store) store.setItem(key, JSON.stringify(value));\n    return value;\n  },\n  local_forget: (key) => {\n    const store = globalThis.localStorage;\n    if (store) store.removeItem(key);\n    return true;\n  },\n});\n\"\"\"\n"; maca_write_file(maca_cat(maca_cat("", root), "/web/storage.maca"), web_storage); const char* web_time = "// web/time: the clock on the wall the page is hanging on.\n//\n// The host answers with the parts of the local time and nothing else; what\n// those parts read as is `web/format`, which every target can run.\n\nimport { clock, clock12, stamp } from web/format\n\n/// The local time as `[year, month, day, hour, minute, second]`.\nnow_parts() -> int[]\n\n/// Repaint the view every `ms` milliseconds, and answer the timer that does it.\nevery_ms(ms: int) -> int\n\n/// Stop the repainting `every_ms` started.\nstop_every(timer: int) -> bool\n\n/// The local time as a 24-hour clock reads it.\nclock_time() -> str {\n    p = now_parts()\n    clock(p.get(3), p.get(4))\n}\n\n/// The local time as a 12-hour clock reads it.\nclock_time12() -> str {\n    p = now_parts()\n    clock12(p.get(3), p.get(4))\n}\n\n/// Today, as one sortable stamp.\nclock_date() -> str {\n    p = now_parts()\n    stamp(p.get(0), p.get(1), p.get(2))\n}\n\nimport \"time.js\" \"\"\"\nmaca.provide({\n  now_parts: () => {\n    const d = new Date();\n    return [\n      d.getFullYear(), d.getMonth() + 1, d.getDate(),\n      d.getHours(), d.getMinutes(), d.getSeconds(),\n    ];\n  },\n  every_ms: (ms) => setInterval(() => maca.refresh(), ms),\n  stop_every: (timer) => { clearInterval(timer); return true },\n});\n\"\"\"\n"; maca_write_file(maca_cat(maca_cat("", root), "/web/time.maca"), web_time); const char* http_dev = "import { Request, query_value } from http/request\nimport { Response, json } from http/response\nimport { runtime_script } from signal/dom\n\n/// Where a builder publishes patches and a poll reads them.\nFeed = { dir: str }\n\n/// A feed under `dir`, which is created if it is not there yet.\nfeed(dir: str) -> Feed {\n    make_dir(dir)\n    Feed { dir = dir }\n}\n\nKeep = 16\n\nStep = 100\n\n/// The path the browser polls.\nPollPath = \"/_maca/hmr\"\n\n/// Publish `ops` as generation `gen`, and say whether it went.\npublish(f: Feed, gen: int, ops: str) -> bool {\n    if write_file(patch_file(f, gen), ops) {\n        remove_file(patch_file(f, gen - Keep))\n        write_file(f.dir ++ \"/generation\", str(gen) ++ \"\\n\")\n    } else {\n        false\n    }\n}\n\n/// The newest generation published, or 0 when nothing has been.\ngeneration(f: Feed) -> int {\n    at = f.dir ++ \"/generation\"\n\n    if !file_exists(at) {\n        0\n    } else {\n        int(read_file(at).trim())\n    }\n}\n\n/// The ops published as `gen`, or \"[]\" when that generation is gone.\npatch_of(f: Feed, gen: int) -> str {\n    at = patch_file(f, gen)\n\n    if !file_exists(at) {\n        \"[]\"\n    } else {\n        read_file(at)\n    }\n}\n\npatch_file(f: Feed, gen: int) -> str => f.dir ++ \"/\" ++ str(gen) ++ \".json\"\n\n/// Is this the dev channel's own request?\nis_poll(req: Request) -> bool => req.path == PollPath\n\n/// Answer a poll, holding the connection for up to `budget_ms`.\nanswer(f: Feed, req: Request, budget_ms: int) -> Response =>\n    json(waited(f, seen(req), budget_ms))\n\nFresh = -1\n\nseen(req: Request) -> int {\n    named = query_value(req, \"gen\")\n\n    if named == \"\" {\n        Fresh\n    } else if int(named) < 0 {\n        0\n    } else {\n        int(named)\n    }\n}\n\nwaited(f: Feed, since: int, budget_ms: int) -> str {\n    left = budget_ms\n    gen = generation(f)\n\n    while gen <= since && left > 0 {\n        sleep_ms(Step)\n        left = left - Step\n        gen = generation(f)\n    }\n\n    message(f, since, gen)\n}\n\n/// One poll's answer, as the JSON the client reads.\nmessage(f: Feed, since: int, gen: int) -> str {\n    if since == Fresh || gen <= since {\n        \"\\{\\\"gen\\\":{gen}\\}\"\n    } else if !have_all(f, since, gen) {\n        \"\\{\\\"gen\\\":{gen},\\\"reload\\\":true\\}\"\n    } else {\n        \"\\{\\\"gen\\\":{gen},\\\"ops\\\":\" ++ ops_since(f, since, gen) ++ \"\\}\"\n    }\n}\n\n/// Every generation after `since` up to `gen`, as one array of ops in published order.\nops_since(f: Feed, since: int, gen: int) -> str =>\n    \"[\" ++ merged(f, since + 1, gen, []).join(\",\") ++ \"]\"\n\nmerged(f: Feed, at: int, gen: int, acc: str[]) -> str[] {\n    if at > gen {\n        acc\n    } else {\n        body = unbracketed(patch_of(f, at))\n        merged(f, at + 1, gen, body == \"\" ? acc : acc.push(body))\n    }\n}\n\nunbracketed(arr: str) -> str {\n    t = arr.trim()\n\n    if t.length() < 2 {\n        \"\"\n    } else {\n        t.slice(1, t.length() - 1).trim()\n    }\n}\n\n/// Is every generation between `since` and `gen` still on disk, whole?\nhave_all(f: Feed, since: int, gen: int) -> bool => present(f, since + 1, gen)\n\npresent(f: Feed, at: int, gen: int) -> bool {\n    if at > gen {\n        true\n    } else if !whole(f, at) {\n        false\n    } else {\n        present(f, at + 1, gen)\n    }\n}\n\nwhole(f: Feed, gen: int) -> bool {\n    at = patch_file(f, gen)\n\n    file_exists(at) && read_file(at).trim().ends_with(\"]\")\n}\n\n/// What a dev-mode page needs in its `<head>`, and the whole of it.\ndev_head() -> str => runtime_script() ++ poll_script()\n\n/// The poll loop, in a `<script>`.\npoll_script() -> str => script(poll_js())\n\npoll_js() -> str =>\n    \"window.macaDevPath=\\\"\" ++ PollPath ++ \"\\\";\\n\" ++ Poller\n\nPoller = \"\"\"\n(function () {\n  var gen = -1;\n  function poll() {\n    var x = new XMLHttpRequest();\n    x.open(\"GET\", window.macaDevPath + (gen < 0 ? \"\" : \"?gen=\" + gen), true);\n    x.onload = function () {\n      var m = null;\n      try { m = JSON.parse(x.responseText); } catch (e) { m = null; }\n      if (!m) { setTimeout(poll, 1000); return; }\n      if (m.reload) { location.reload(); return; }\n      if (m.gen > gen) {\n        gen = m.gen;\n        if (m.ops && m.ops.length && window.macaSignal) window.macaSignal(m.ops);\n        setTimeout(poll, 0);\n      } else {\n        setTimeout(poll, 250);\n      }\n    };\n    x.onerror = function () { setTimeout(poll, 1000); };\n    x.send();\n  }\n  if (document.readyState === \"loading\")\n    document.addEventListener(\"DOMContentLoaded\", poll);\n  else poll();\n})();\n\"\"\"\n"; maca_write_file(maca_cat(maca_cat("", root), "/http/dev.maca"), http_dev); const char* http_request = "import { split_once, index_of_from } from std/text\n\n/// One request, parsed.\nRequest = {\n    method:  str\n    /// The path with the query string removed, and percent-escapes decoded.\n    path:    str\n    /// Everything after `?`, undecoded.\n    query:   str\n    version: str\n    /// The header block, still raw.\n    headers: str\n    body:    str\n}\n\n/// Parse a raw request.\nparse_request(raw: str) -> Request {\n    split = split_head(raw)\n    head = normalize_endings(split.get(0))\n    body = split.get(1)\n    line_rest = split_once(head, \"\\n\")\n    parts = line_rest.get(0).split(\" \").filter(w => w != \"\")\n    target = if parts.length() > 1 { parts.get(1) } else { \"\" }\n    path_query = split_once(target, \"?\")\n\n    Request {\n        method = if parts.length() > 2 { parts.get(0).upper() } else { \"\" },\n        path = percent_decode(path_query.get(0)),\n        query = path_query.get(1),\n        version = if parts.length() > 2 { parts.get(2) } else { \"\" },\n        headers = line_rest.get(1),\n        body = body\n    }\n}\n\nsplit_head(raw: str) -> str[] {\n    crlf = raw.index_of(\"\\r\\n\\r\\n\")\n    lf = raw.index_of(\"\\n\\n\")\n\n    if crlf >= 0 && (lf < 0 || crlf < lf) {\n        [raw.substr(0, crlf), raw.substr(crlf + 4, raw.length())]\n    } else if lf >= 0 {\n        [raw.substr(0, lf), raw.substr(lf + 2, raw.length())]\n    } else {\n        [raw, \"\"]\n    }\n}\n\nnormalize_endings(raw: str) -> str =>\n    raw.replace(\"\\r\\n\", \"\\n\")\n\n/// A header's value, or \"\" when it is absent.\nheader(r: Request, name: str) -> str =>\n    scan_headers(r.headers.split(\"\\n\"), 0, name.lower())\n\nscan_headers(lines: str[], i: int, want: str) -> str {\n    if i >= lines.length() {\n        \"\"\n    } else if header_name(lines.get(i)) == want {\n        header_value(lines.get(i))\n    } else {\n        scan_headers(lines, i + 1, want)\n    }\n}\n\nheader_name(line: str) -> str =>\n    split_once(line, \":\").get(0).trim().lower()\n\nheader_value(line: str) -> str =>\n    split_once(line, \":\").get(1).trim()\n\n/// A query parameter's value, or \"\" when absent.\nquery_value(r: Request, name: str) -> str =>\n    scan_pairs(r.query.split(\"&\"), 0, name)\n\n/// The same, over a form-encoded body: `application/x-www-form-urlencoded`.\nform_value(r: Request, name: str) -> str =>\n    scan_pairs(r.body.split(\"&\"), 0, name)\n\nscan_pairs(pairs: str[], i: int, want: str) -> str {\n    if i >= pairs.length() {\n        \"\"\n    } else if split_once(pairs.get(i), \"=\").get(0) == want {\n        percent_decode(split_once(pairs.get(i), \"=\").get(1).replace(\"+\", \" \"))\n    } else {\n        scan_pairs(pairs, i + 1, want)\n    }\n}\n\n/// Decode `%XX` escapes.\npercent_decode(s: str) -> str =>\n    decode_from(s, 0, \"\")\n\ndecode_from(s: str, i: int, acc: str) -> str {\n    if i >= s.length() {\n        acc\n    } else if s.at(i) == \"%\" && i + 2 < s.length() {\n        code = hex_pair(s.at(i + 1), s.at(i + 2))\n\n        if code < 0 {\n            decode_from(s, i + 1, acc ++ s.at(i))\n        } else {\n            decode_from(s, i + 3, acc ++ chr(code))\n        }\n    } else {\n        decode_from(s, i + 1, acc ++ s.at(i))\n    }\n}\n\nhex_pair(hi: str, lo: str) -> int {\n    h = hex_digit(hi)\n    l = hex_digit(lo)\n\n    if h < 0 || l < 0 {\n        -1\n    } else {\n        h * 16 + l\n    }\n}\n\nhex_digit(c: str) -> int {\n    b = ord(c)\n\n    if b >= Zero && b <= Nine {\n        b - Zero\n    } else if b >= LowerA && b <= LowerF {\n        10 + b - LowerA\n    } else if b >= UpperA && b <= UpperF {\n        10 + b - UpperA\n    } else {\n        -1\n    }\n}\n\nZero = ord(\"0\")\nNine = ord(\"9\")\nLowerA = ord(\"a\")\nLowerF = ord(\"f\")\nUpperA = ord(\"A\")\nUpperF = ord(\"F\")\n"; maca_write_file(maca_cat(maca_cat("", root), "/http/request.maca"), http_request); const char* http_response = "import { reason, content_type } from http/status\n\n/// A response, before it is bytes.\nResponse = {\n    status: int\n    /// Extra headers, each `Name: value`, without line endings.\n    headers: str[]\n    body:    str\n    /// Answer this one and hang up.\n    close:   bool\n}\n\n/// The common case: a body, a content type, and 200.\nok(body: str, kind: str) -> Response =>\n    Response { status = 200, headers = [\"Content-Type: \" ++ kind],\n               body = body, close = false }\n\n/// An HTML page.\nhtml(body: str) -> Response =>\n    ok(body, \"text/html; charset=utf-8\")\n\n/// Plain text.\ntext(body: str) -> Response =>\n    ok(body, \"text/plain; charset=utf-8\")\n\n/// A JSON document.\njson(body: str) -> Response =>\n    ok(body, \"application/json; charset=utf-8\")\n\n/// A file's contents, typed by its name's extension.\nfile(name: str, body: str) -> Response =>\n    ok(body, content_type(name))\n\n/// Any status with a plain-text body naming it, for the answers that are the status.\nstatus(code: int) -> Response =>\n    Response { status = code, headers = [\"Content-Type: text/plain; charset=utf-8\"],\n               body = \"{code} {reason(code)}\\n\", close = code >= 400 }\n\n/// Send the reader somewhere else.\nredirect(code: int, location: str) -> Response =>\n    Response { status = code, headers = [\"Location: \" ++ location],\n               body = \"\", close = false }\n\n/// One more header.\nwith_header(r: Response, line: str) -> Response =>\n    r with { headers = r.headers.push(line) }\n\n/// Answer and hang up.\nclosing(r: Response) -> Response =>\n    r with { close = true }\n\n/// Render a response to the bytes that go on the wire.\nrender(r: Response) -> str =>\n    \"HTTP/1.1 {r.status} {reason(r.status)}\\r\\n\"\n        ++ header_lines(r.headers, 0, \"\")\n        ++ \"Content-Length: {r.body.length()}\\r\\n\"\n        ++ \"Connection: \" ++ (r.close ? \"close\" : \"keep-alive\") ++ \"\\r\\n\"\n        ++ \"\\r\\n\"\n        ++ r.body\n\nheader_lines(hs: str[], i: int, acc: str) -> str {\n    if i >= hs.length() {\n        acc\n    } else {\n        header_lines(hs, i + 1, acc ++ hs.get(i) ++ \"\\r\\n\")\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/http/response.maca"), http_response); const char* http_serve = "import { listen } from http/server\nimport { Request } from http/request\nimport { Response, file, status } from http/response\nimport { join, normalize } from std/path\n\nserve(args: str[]) -> int {\n    port = if args.length() > 0 { int(args.get(0)) } else { 8000 }\n    root = if args.length() > 1 { args.get(1) } else { \".\" }\n\n    if !is_dir(root) {\n        err(\"no directory `{root}`\")\n        1\n    } else {\n        info(\"serving {root} on http://localhost:{port}\")\n        listen(port, req => serve_file(root, req))\n    }\n}\n\n/// One file out of `root`, chosen by the request path.\nserve_file(root: str, req: Request) -> Response {\n    if req.method != \"GET\" && req.method != \"HEAD\" {\n        status(405)\n    } else {\n        wanted = under(root, req.path)\n\n        if wanted == \"\" {\n            status(403)\n        } else {\n            read_or_index(wanted)\n        }\n    }\n}\n\nunder(root: str, path: str) -> str {\n    base = real_path(root)\n    joined = join(base, path)\n    resolved = real_path(joined)\n    inside = if resolved == \"\" { normalize(joined) } else { resolved }\n\n    if base != \"\" && (inside == base || inside.starts_with(base ++ \"/\")) {\n        inside\n    } else {\n        \"\"\n    }\n}\n\nread_or_index(path: str) -> Response {\n    target = if is_dir(path) { join(path, \"index.html\") } else { path }\n\n    if !file_exists(target) {\n        status(404)\n    } else {\n        file(target, read_file(target))\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/http/serve.maca"), http_serve); const char* http_server = "import \"http.h\"\n\nimport { parse_request, Request } from http/request\nimport { Response, render, status } from http/response\n\nhttp_listen(port: int) -> int\nhttp_accept_loop(server: int, handler: (str) -> str) -> int\nhttp_fetch(host: str, port: int, request: str) -> str\n\n/// Serve `handler` on `port` until the process ends.\nlisten(port: int, handler) -> int {\n    server = http_listen(port)\n\n    if server < 0 {\n        err(bind_failure(server, port))\n        1\n    } else {\n        http_accept_loop(server, raw => render(answer(handler, raw)))\n        0\n    }\n}\n\nanswer(handler, raw: str) -> Response {\n    r = parse_request(raw)\n\n    if r.method == \"\" {\n        status(400)\n    } else {\n        handler(r)\n    }\n}\n\nbind_failure(code: int, port: int) -> str {\n    if code == -2 {\n        \"port {port} is already in use\"\n    } else if code == -1 {\n        \"could not open a socket\"\n    } else {\n        \"could not listen on port {port}\"\n    }\n}\n\n/// One request against a server, returning the whole reply including headers.\nfetch(host: str, port: int, request: str) -> str =>\n    http_fetch(host, port, request)\n\n/// A `GET` for the common case.\nget(host: str, port: int, path: str) -> str =>\n    fetch(host, port,\n          \"GET {path} HTTP/1.1\\r\\nHost: {host}\\r\\nConnection: close\\r\\n\\r\\n\")\n"; maca_write_file(maca_cat(maca_cat("", root), "/http/server.maca"), http_server); const char* http_status = "/// The reason phrase for a status code.\nreason(code: int) -> str {\n    if code == 200 {\n        \"OK\"\n    } else if code == 201 {\n        \"Created\"\n    } else if code == 204 {\n        \"No Content\"\n    } else if code == 301 {\n        \"Moved Permanently\"\n    } else if code == 302 {\n        \"Found\"\n    } else if code == 304 {\n        \"Not Modified\"\n    } else if code == 400 {\n        \"Bad Request\"\n    } else if code == 401 {\n        \"Unauthorized\"\n    } else if code == 403 {\n        \"Forbidden\"\n    } else if code == 404 {\n        \"Not Found\"\n    } else if code == 405 {\n        \"Method Not Allowed\"\n    } else if code == 409 {\n        \"Conflict\"\n    } else if code == 413 {\n        \"Payload Too Large\"\n    } else if code == 415 {\n        \"Unsupported Media Type\"\n    } else if code == 422 {\n        \"Unprocessable Content\"\n    } else if code == 429 {\n        \"Too Many Requests\"\n    } else if code == 500 {\n        \"Internal Server Error\"\n    } else if code == 501 {\n        \"Not Implemented\"\n    } else if code == 503 {\n        \"Service Unavailable\"\n    } else {\n        class_reason(code)\n    }\n}\n\nclass_reason(code: int) -> str {\n    if code < 200 {\n        \"Informational\"\n    } else if code < 300 {\n        \"Success\"\n    } else if code < 400 {\n        \"Redirection\"\n    } else if code < 500 {\n        \"Client Error\"\n    } else {\n        \"Server Error\"\n    }\n}\n\n/// Did this code succeed?\nis_ok(code: int) -> bool =>\n    code >= 200 && code < 300\n\n/// The MIME type for a filename's extension, `application/octet-stream` when nothing matches.\ncontent_type(path: str) -> str {\n    ext = extension_of(path)\n\n    if ext == \"html\" || ext == \"htm\" {\n        \"text/html; charset=utf-8\"\n    } else if ext == \"css\" {\n        \"text/css; charset=utf-8\"\n    } else if ext == \"js\" || ext == \"mjs\" {\n        \"text/javascript; charset=utf-8\"\n    } else if ext == \"json\" {\n        \"application/json; charset=utf-8\"\n    } else if ext == \"svg\" {\n        \"image/svg+xml\"\n    } else if ext == \"png\" {\n        \"image/png\"\n    } else if ext == \"jpg\" || ext == \"jpeg\" {\n        \"image/jpeg\"\n    } else if ext == \"gif\" {\n        \"image/gif\"\n    } else if ext == \"webp\" {\n        \"image/webp\"\n    } else if ext == \"ico\" {\n        \"image/x-icon\"\n    } else if ext == \"woff2\" {\n        \"font/woff2\"\n    } else if ext == \"wasm\" {\n        \"application/wasm\"\n    } else if ext == \"txt\" || ext == \"md\" {\n        \"text/plain; charset=utf-8\"\n    } else if ext == \"xml\" {\n        \"application/xml\"\n    } else if ext == \"pdf\" {\n        \"application/pdf\"\n    } else {\n        \"application/octet-stream\"\n    }\n}\n\nextension_of(path: str) -> str {\n    segment = last_segment(path)\n    at = last_dot(segment, segment.length() - 1)\n\n    if at < 0 {\n        \"\"\n    } else {\n        segment.substr(at + 1, segment.length()).lower()\n    }\n}\n\nlast_segment(path: str) -> str {\n    at = last_slash(path, path.length() - 1)\n\n    if at < 0 {\n        path\n    } else {\n        path.substr(at + 1, path.length())\n    }\n}\n\nlast_slash(s: str, i: int) -> int {\n    if i < 0 {\n        -1\n    } else if s.at(i) == \"/\" {\n        i\n    } else {\n        last_slash(s, i - 1)\n    }\n}\n\nlast_dot(s: str, i: int) -> int {\n    if i <= 0 {\n        -1\n    } else if s.at(i) == \".\" {\n        i\n    } else {\n        last_dot(s, i - 1)\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/http/status.maca"), http_status); const char* signal_dom = "import { escape_html, index_of_from } from std/text\nimport { Store, get, changed } from signal/store\n\n/// One node to update: the key that changed, its new value, and the selector that finds every node bound to it.\nOp = {\n    key: str,\n    value: str,\n    selector: str,\n}\n\n/// A `<tag>` whose text is `key`'s value.\ntext_node(s: Store, tag: str, key: str) -> str =>\n    element(tag, data-signal=key, escape_html(get(s, key)))\n\n/// A `<tag>` whose `class` attribute is `key`'s value, with `body` inside it.\nclass_node(s: Store, tag: str, key: str, body: str) -> str =>\n    element(tag, data-signal=key, data-signal-as=\"class\", class=get(s, key),\n        body)\n\n/// An `<input>` whose value is `key`'s value.\nvalue_input(s: Store, key: str) -> str =>\n    element(\"input\", data-signal=key, data-signal-as=\"value\",\n        value=get(s, key), \"\")\n\n/// A `<tag>` whose *inner markup* is `key`'s value: a region of the page that a rebuild replaces whole.\nhtml_node(s: Store, tag: str, key: str) -> str =>\n    element(tag, data-signal=key, data-signal-as=\"html\", get(s, key))\n\n/// The selector matching every node bound to `key`.\nselector(key: str) -> str => \"[data-signal=\\\"\" ++ css_escaped(key) ++ \"\\\"]\"\n\ncss_escaped(key: str) -> str =>\n    key.replace(\"\\\\\", \"\\\\\\\\\").replace(\"\\\"\", \"\\\\\\\"\")\n\n/// One op per key that changed since the last `clear_changed`, in the order they changed.\npatch(s: Store) -> Op[] => ops_from(s, changed(s), 0, [])\n\nops_from(s: Store, ks: str[], i: int, acc: Op[]) -> Op[] {\n    if i >= ks.length() {\n        acc\n    } else {\n        op = Op {\n            key = ks.get(i),\n            value = get(s, ks.get(i)),\n            selector = selector(ks.get(i)),\n        }\n        ops_from(s, ks, i + 1, acc.push(op))\n    }\n}\n\n/// One op as a line of text: what a native build prints instead of patching.\ndescribe(op: Op) -> str =>\n    \"{op.key} {op.selector} <- {shown(op.value)}\"\n\n/// The whole patch as lines, one per op.\ndescribe_all(ops: Op[]) -> str[] => lines_from(ops, 0, [])\n\nlines_from(ops: Op[], i: int, acc: str[]) -> str[] {\n    if i >= ops.length() {\n        acc\n    } else {\n        lines_from(ops, i + 1, acc.push(describe(ops.get(i))))\n    }\n}\n\n/// The JavaScript that applies the current patch, or \"\" when nothing changed.\npatch_script(s: Store) -> str {\n    ops = patch(s)\n\n    if ops.length() == 0 {\n        \"\"\n    } else {\n        \"macaSignal(\" ++ ops_json(ops) ++ \");\"\n    }\n}\n\n/// The current patch as a JSON array, `[]` when nothing changed.\npatch_json(s: Store) -> str => ops_json(patch(s))\n\nops_json(ops: Op[]) -> str => \"[\" ++ encode(ops, 0, []).join(\",\") ++ \"]\"\n\nencode(ops: Op[], i: int, acc: str[]) -> str[] {\n    if i >= ops.length() {\n        acc\n    } else {\n        op = ops.get(i)\n        obj = \"\\{\\\"key\\\":\" ++ quoted(op.key) ++ \",\\\"value\\\":\"\n            ++ quoted(op.value) ++ \"\\}\"\n        encode(ops, i + 1, acc.push(obj))\n    }\n}\n\nescaped_value(v: str) -> str =>\n    v.replace(\"\\\\\", \"\\\\\\\\\")\n        .replace(\"\\\"\", \"\\\\\\\"\")\n        .replace(\"\\n\", \"\\\\n\")\n        .replace(\"\\r\", \"\\\\r\")\n\nshown(v: str) -> str => \"\\\"\" ++ escaped_value(v) ++ \"\\\"\"\n\nquoted(v: str) -> str =>\n    \"\\\"\" ++ escaped_value(v).replace(\"<\", \"\\\\u003c\") ++ \"\\\"\"\n\n/// `ops` applied to the markup they were computed against.\napply_patch(page: str, ops: Op[]) -> str => applied(page, ops, 0)\n\napplied(page: str, ops: Op[], i: int) -> str {\n    if i >= ops.length() {\n        page\n    } else {\n        applied(apply_from(page, ops.get(i), 0), ops, i + 1)\n    }\n}\n\napply_from(page: str, op: Op, at: int) -> str {\n    found = index_of_from(page, marker(op.key), at)\n\n    if found < 0 {\n        page\n    } else {\n        patch_node(page, op, tag_open(page, found))\n    }\n}\n\npatch_node(page: str, op: Op, lt: int) -> str {\n    gt = index_of_from(page, \">\", lt)\n    tag = tag_name(page, lt)\n    shows = attr_in(page.slice(lt, gt + 1), \"data-signal-as\")\n\n    if shows == \"\" || shows == \"html\" {\n        patch_children(page, op, tag, gt + 1, shows == \"html\")\n    } else {\n        patch_attr(page, op, lt, gt, shows)\n    }\n}\n\npatch_children(page: str, op: Op, tag: str, from: int, raw: bool) -> str {\n    close = close_at(page, tag, from)\n    shown = raw ? op.value : escape_html(op.value)\n    next = page.slice(0, from) ++ shown ++ page.slice(close, page.length())\n\n    apply_from(next, op, from + shown.length())\n}\n\npatch_attr(page: str, op: Op, lt: int, gt: int, name: str) -> str {\n    rebuilt = with_attr(page.slice(lt, gt + 1), name, op.value)\n    next = page.slice(0, lt) ++ rebuilt ++ page.slice(gt + 1, page.length())\n\n    apply_from(next, op, lt + rebuilt.length())\n}\n\nmarker(key: str) -> str => \"data-signal=\\\"\" ++ escape_html(key) ++ \"\\\"\"\n\ntag_open(page: str, at: int) -> int {\n    if at <= 0 {\n        0\n    } else if page.at(at) == \"<\" {\n        at\n    } else {\n        tag_open(page, at - 1)\n    }\n}\n\ntag_name(page: str, lt: int) -> str => name_from(page, lt + 1, \"\")\n\nname_from(page: str, i: int, acc: str) -> str {\n    if i >= page.length() || !is_name_char(page.at(i)) {\n        acc\n    } else {\n        name_from(page, i + 1, acc ++ page.at(i))\n    }\n}\n\nis_name_char(ch: str) -> bool => ch.is_alpha() || ch.is_ascii_digit()\n\nclose_at(page: str, tag: str, from: int) -> int =>\n    close_scan(page, tag, from, 0)\n\nclose_scan(page: str, tag: str, at: int, depth: int) -> int {\n    closing = index_of_from(page, \"</\" ++ tag ++ \">\", at)\n    opening = next_open(page, tag, at)\n\n    if closing < 0 {\n        page.length()\n    } else if opening >= 0 && opening < closing {\n        close_scan(page, tag, opening + tag.length() + 1, depth + 1)\n    } else if depth == 0 {\n        closing\n    } else {\n        close_scan(page, tag, closing + tag.length() + 3, depth - 1)\n    }\n}\n\nnext_open(page: str, tag: str, at: int) -> int {\n    found = index_of_from(page, \"<\" ++ tag, at)\n    after = found + tag.length() + 1\n\n    if found < 0 {\n        -1\n    } else if after >= page.length() || !is_name_char(page.at(after)) {\n        found\n    } else {\n        next_open(page, tag, found + 1)\n    }\n}\n\nwith_attr(open: str, name: str, v: str) -> str {\n    pat = \" \" ++ name ++ \"=\\\"\"\n    at = open.index_of(pat)\n    end = index_of_from(open, \"\\\"\", at + pat.length())\n\n    if at < 0 {\n        open.slice(0, open.length() - 1) ++ pat ++ escape_html(v) ++ \"\\\">\"\n    } else {\n        open.slice(0, at + pat.length()) ++ escape_html(v)\n            ++ open.slice(end, open.length())\n    }\n}\n\nattr_in(open: str, name: str) -> str {\n    pat = \" \" ++ name ++ \"=\\\"\"\n    at = open.index_of(pat)\n\n    if at < 0 {\n        \"\"\n    } else {\n        open.slice(at + pat.length(),\n                   index_of_from(open, \"\\\"\", at + pat.length()))\n    }\n}\n\n/// `runtime()` inside a `<script>`, ready to drop into a page's `<head>`.\nruntime_script() -> str => element(\"script\", runtime())\n\n/// The patcher, as JavaScript source.\nruntime() -> str => \"\"\"\nwindow.macaSignal = function (ops) {\n  for (var i = 0; i < ops.length; i++) {\n    var op = ops[i];\n    var key = op.key.replace(/[\\\\\"]/g, \"\\\\$&\");\n    var nodes = document.querySelectorAll('[data-signal=\"' + key + '\"]');\n    for (var j = 0; j < nodes.length; j++) {\n      var el = nodes[j];\n      var as = el.getAttribute(\"data-signal-as\");\n      if (!as) el.textContent = op.value;\n      else if (as === \"html\") el.innerHTML = op.value;\n      else if (as === \"value\") el.value = op.value;\n      else el.setAttribute(as, op.value);\n    }\n  }\n};\n\"\"\"\n\n/// An HTML comment saying the page was rendered once and is not live.\nstatic_note() -> str =>\n    \"<!-- rendered once by a native build; no DOM to patch -->\"\n"; maca_write_file(maca_cat(maca_cat("", root), "/signal/dom.maca"), signal_dom); const char* signal_store = "/// A store: every key's value, and the bookkeeping that makes a change to one of them observable.\nStore = {\n    values: Map str str,\n    /// Bumped only when a write really changed a value.\n    versions: Map str int,\n    deps: Map str str,\n    /// For a computed, the dependency versions at its last recomputation.\n    basis: Map str str,\n    /// Computed keys in declaration order, which `refresh` relies on.\n    computeds: str[],\n    dirty: str[],\n    watchers: Map str str,\n    acked: Map str str,\n}\n\nSep = \"\\n\"\n\nUnseen = \"?\"\n\n/// An empty store.\nstore() -> Store {\n    values: Map str str = map()\n    versions: Map str int = map()\n    deps: Map str str = map()\n    basis: Map str str = map()\n    watchers: Map str str = map()\n    acked: Map str str = map()\n\n    Store {\n        values = values,\n        versions = versions,\n        deps = deps,\n        basis = basis,\n        computeds = [],\n        dirty = [],\n        watchers = watchers,\n        acked = acked,\n    }\n}\n\n/// The value of `key`, or \"\" when it was never written.\nget(s: Store, key: str) -> str => s.values.get(key, \"\")\n\n/// The value of `key`, or `fallback` when it was never written.\nvalue(s: Store, key: str, fallback: str) -> str =>\n    s.values.get(key, fallback)\n\n/// Has `key` ever been written?\nhas(s: Store, key: str) -> bool => s.values.has(key)\n\n/// Every key the store holds, atoms and computeds alike.\nkeys(s: Store) -> str[] => s.values.keys()\n\n/// How many times `key` has actually changed.\nversion(s: Store, key: str) -> int => s.versions.get(key, 0)\n\n/// `key` read as a number, or `fallback` when it was never written.\nnum(s: Store, key: str, fallback: int) -> int {\n    if has(s, key) {\n        int(get(s, key))\n    } else {\n        fallback\n    }\n}\n\n/// Write `key`.\nset(s: Store, key: str, v: str) -> Store {\n    settled = is_computed(s, key) ? mark_fresh(s, key) : s\n    seen = version(settled, key)\n\n    if has(settled, key) && get(settled, key) == v {\n        settled\n    } else {\n        settled with {\n            values = settled.values.set(key, v),\n            versions = settled.versions.set(key, seen + 1),\n            dirty = settled.dirty.contains(key)\n                ? settled.dirty\n                : settled.dirty.push(key),\n        }\n    }\n}\n\n/// `set`, spelled for a number.\nset_num(s: Store, key: str, n: int) -> Store => set(s, key, str(n))\n\n/// Declare `key` as derived from `deps`.\ncomputed(s: Store, key: str, deps: str[]) -> Store {\n    known = is_computed(s, key)\n\n    s with {\n        deps = s.deps.set(key, pack(deps)),\n        basis = s.basis.remove(key),\n        computeds = known ? s.computeds : s.computeds.push(key),\n    }\n}\n\n/// Was `key` declared with `computed`?\nis_computed(s: Store, key: str) -> bool => s.deps.has(key)\n\n/// Every computed, in declaration order.\nderived(s: Store) -> str[] => s.computeds\n\n/// What `key` was declared to derive from, in declared order.\ndeps_of(s: Store, key: str) -> str[] => unpack(s.deps.get(key, \"\"))\n\n/// The current values of `key`'s dependencies, in declared order.\ninputs(s: Store, key: str) -> str[] => values_of(s, deps_of(s, key), 0, [])\n\nvalues_of(s: Store, ks: str[], i: int, acc: str[]) -> str[] {\n    if i >= ks.length() {\n        acc\n    } else {\n        values_of(s, ks, i + 1, acc.push(get(s, ks.get(i))))\n    }\n}\n\n/// Does `key` need recomputing?\nstale(s: Store, key: str) -> bool {\n    if !is_computed(s, key) {\n        false\n    } else {\n        fingerprint(s, deps_of(s, key)) != s.basis.get(key, Unseen)\n    }\n}\n\n/// The first computed in declaration order that needs recomputing, or \"\" when the graph has settled.\nnext_stale(s: Store) -> str => first_stale(s, 0)\n\nfirst_stale(s: Store, i: int) -> str {\n    if i >= s.computeds.length() {\n        \"\"\n    } else if stale(s, s.computeds.get(i)) {\n        s.computeds.get(i)\n    } else {\n        first_stale(s, i + 1)\n    }\n}\n\n/// Recompute `key` if a dependency has changed since it was last computed, and do nothing at all otherwise.\nrefresh(s: Store, key: str, f) -> Store {\n    if !stale(s, key) {\n        s\n    } else {\n        fresh: str = f(inputs(s, key))\n        set(s, key, fresh)\n    }\n}\n\nmark_fresh(s: Store, key: str) -> Store =>\n    s with { basis = s.basis.set(key, fingerprint(s, deps_of(s, key))) }\n\nfingerprint(s: Store, ks: str[]) -> str => pack(versions_of(s, ks, 0, []))\n\nversions_of(s: Store, ks: str[], i: int, acc: str[]) -> str[] {\n    if i >= ks.length() {\n        acc\n    } else {\n        versions_of(s, ks, i + 1, acc.push(str(version(s, ks.get(i)))))\n    }\n}\n\n/// The keys that changed since the last `clear_changed`, in the order they changed, each appearing once.\nchanged(s: Store) -> str[] => s.dirty\n\n/// Did `key` change since the last `clear_changed`?\ntouched(s: Store, key: str) -> bool => s.dirty.contains(key)\n\n/// Forget the changed keys.\nclear_changed(s: Store) -> Store => s with { dirty = [] }\n\n/// Subscribe `name` to `keys`.\nwatch(s: Store, name: str, keys: str[]) -> Store =>\n    s with {\n        watchers = s.watchers.set(name, pack(keys)),\n        acked = s.acked.set(name, fingerprint(s, keys)),\n    }\n\n/// Drop a subscriber.\nunwatch(s: Store, name: str) -> Store =>\n    s with {\n        watchers = s.watchers.remove(name),\n        acked = s.acked.remove(name),\n    }\n\n/// Is `name` subscribed?\nwatching(s: Store, name: str) -> bool => s.watchers.has(name)\n\n/// The keys `name` watches that have changed since it last looked, in the order it named them.\npending(s: Store, name: str) -> str[] {\n    keys = unpack(s.watchers.get(name, \"\"))\n    seen = unpack(s.acked.get(name, \"\"))\n    behind(s, keys, seen, 0, [])\n}\n\nbehind(s: Store, ks: str[], seen: str[], i: int, acc: str[]) -> str[] {\n    if i >= ks.length() {\n        acc\n    } else if seen.get(i) == str(version(s, ks.get(i))) {\n        behind(s, ks, seen, i + 1, acc)\n    } else {\n        behind(s, ks, seen, i + 1, acc.push(ks.get(i)))\n    }\n}\n\n/// Mark `name` as having seen the current values.\nack(s: Store, name: str) -> Store {\n    if !watching(s, name) {\n        s\n    } else {\n        keys = unpack(s.watchers.get(name, \"\"))\n        s with { acked = s.acked.set(name, fingerprint(s, keys)) }\n    }\n}\n\npack(xs: str[]) -> str => pack_from(xs, 0, \"\")\n\npack_from(xs: str[], i: int, acc: str) -> str {\n    if i >= xs.length() {\n        acc\n    } else {\n        pack_from(xs, i + 1, acc ++ escaped(xs.get(i)) ++ Sep)\n    }\n}\n\nescaped(x: str) -> str => x.replace(\"\\\\\", \"\\\\\\\\\").replace(Sep, \"\\\\n\")\n\nunpack(packed: str) -> str[] => unpack_from(packed, 0, \"\", [])\n\nunpack_from(s: str, i: int, cur: str, acc: str[]) -> str[] {\n    if i >= s.length() {\n        cur == \"\" ? acc : acc.push(cur)\n    } else if s.at(i) == \"\\\\\" && i + 1 < s.length() {\n        c = s.at(i + 1)\n        unpack_from(s, i + 2, cur ++ (c == \"n\" ? Sep : c), acc)\n    } else if s.at(i) == Sep {\n        unpack_from(s, i + 1, \"\", acc.push(cur))\n    } else {\n        unpack_from(s, i + 1, cur ++ s.at(i), acc)\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/signal/store.maca"), signal_store); const char* profile_flame = "import profile/trace\nimport { paint, bold, dim, yellow, width, pad, pad_left } from cli/style\nimport { escape_html } from std/text\n\nScale = {\n    base: int,\n    total: int,\n    cols: int,\n}\n\nscale_of(t: Trace, cols: int) -> Scale =>\n    Scale { base = origin(t), total = wall(t), cols = cols }\n\ncolumn(sc: Scale, at: int) -> int {\n    if sc.total <= 0 {\n        0\n    } else {\n        (at - sc.base) * sc.cols / sc.total\n    }\n}\n\n/// The trace as a text flame chart `cols` columns wide.\nflame(t: Trace, cols: int) -> str {\n    if span_count(t) == 0 {\n        dim(\"(nothing recorded)\")\n    } else {\n        rows = chart_rows(t, scale_of(t, cols), 0, [])\n\n        chart_head(t) ++ \"\\n\" ++ rows.join(\"\\n\") ++ leak_note(t)\n    }\n}\n\nchart_head(t: Trace) -> str {\n    seen = plural(span_count(t), \"span\") ++ \", \" ++ plural(levels(t), \"level\")\n    counts = \", {wall(t)}ms, \" ++ seen\n\n    bold(t.label) ++ dim(counts)\n}\n\nplural(n: int, noun: str) -> str {\n    ending = n == 1 ? \"\" : \"s\"\n\n    \"{n} {noun}{ending}\"\n}\n\nleak_note(t: Trace) -> str {\n    open = leaked(t)\n\n    if open.length() == 0 {\n        \"\"\n    } else {\n        \"\\n\" ++ yellow(\"!\") ++ \" never closed: \" ++ open.join(\", \")\n    }\n}\n\nchart_rows(t: Trace, sc: Scale, d: int, acc: str[]) -> str[] {\n    if d >= levels(t) {\n        acc\n    } else {\n        row = lay_out(t, sc, level(t, d), 0, 0, \"\")\n        chart_rows(t, sc, d + 1, acc.push(row))\n    }\n}\n\nlay_out(t: Trace, sc: Scale, ids: int[], i: int, cursor: int,\n        acc: str) -> str {\n    if i >= ids.length() {\n        acc\n    } else {\n        s = t.spans.get(ids.get(i))\n        from = bar_start(sc, s, cursor)\n        w = bar_width(sc, s, from)\n        gap = \" \".repeat(from - cursor)\n        drawn = acc ++ gap ++ tint(ids.get(i), bar_text(s, w))\n\n        lay_out(t, sc, ids, i + 1, from + w, drawn)\n    }\n}\n\nbar_start(sc: Scale, s: Span, cursor: int) -> int {\n    left = column(sc, s.start)\n\n    left < cursor ? cursor : left\n}\n\nbar_width(sc: Scale, s: Span, from: int) -> int {\n    w = column(sc, s.end) - from\n\n    w < 1 ? 1 : w\n}\n\nbar_text(s: Span, w: int) -> str {\n    if w < 3 {\n        \"▏\".repeat(w)\n    } else {\n        \"[\" ++ inside(s.name, duration(s), w - 2) ++ \"]\"\n    }\n}\n\ninside(name: str, ms: int, room: int) -> str {\n    full = \"{name} {ms}ms\"\n\n    if width(full) <= room {\n        pad(full, room)\n    } else if width(name) <= room {\n        pad(name, room)\n    } else {\n        pad(fit(name, room - 1) ++ \"…\", room)\n    }\n}\n\n/// `s` padded out to `w` columns, counting what shows rather than what is stored.\nfit(s: str, n: int) -> str {\n    if width(s) <= n {\n        s\n    } else {\n        s.slice(0, widest_prefix(s, n, 0, 0))\n    }\n}\n\nwidest_prefix(s: str, n: int, i: int, best: int) -> int {\n    if i > s.length() {\n        best\n    } else if !on_boundary(s, i) {\n        widest_prefix(s, n, i + 1, best)\n    } else if width(s.slice(0, i)) > n {\n        best\n    } else {\n        widest_prefix(s, n, i + 1, i)\n    }\n}\n\non_boundary(s: str, i: int) -> bool {\n    if i >= s.length() {\n        true\n    } else {\n        b = ord(s.at(i))\n\n        b < 128 || b >= 192\n    }\n}\n\ntint(i: int, s: str) -> str => paint(sgr(i), s)\n\nsgr(i: int) -> str {\n    codes = [\"36\", \"32\", \"33\", \"34\", \"35\", \"96\"]\n\n    codes.get(i % codes.length())\n}\n\n/// The same chart as a self-contained SVG `px` pixels wide.\nflame_svg(t: Trace, px: int) -> str => flame_svg_in(t, px, \"ms\")\n\n/// The same SVG over a run counted in `unit` rather than in milliseconds.\nflame_svg_in(t: Trace, px: int, unit: str) -> str {\n    inset = 8\n    rows = levels(t)\n    high = svg_head_h() + rows * svg_row() + inset\n    sc = scale_of(t, px - inset * 2)\n    body = svg_frames(t, sc, inset, 0, \"\", unit)\n\n    svg_open(px, high) ++ svg_backdrop(t, px, high, inset, unit) ++ body\n        ++ \"</svg>\\n\"\n}\n\nsvg_head_h() -> int => 38\n\nsvg_row() -> int => 22\n\nsvg_open(px: int, high: int) -> str {\n    ns = \"xmlns=\\\"http://www.w3.org/2000/svg\\\"\"\n    box = \"viewBox=\\\"0 0 {px} {high}\\\"\"\n    face = \"font-family=\\\"'JetBrainsMono Nerd Font', monospace\\\" font-size=\\\"11\\\"\"\n\n    \"<svg {ns} width=\\\"{px}\\\" height=\\\"{high}\\\" {box} {face}>\\n\"\n}\n\nsvg_backdrop(t: Trace, px: int, high: int, inset: int,\n             unit: str) -> str {\n    back = \"<rect width=\\\"{px}\\\" height=\\\"{high}\\\" fill=\\\"#12121a\\\"/>\\n\"\n    name = escape_html(t.label)\n    seen = plural(span_count(t), \"span\") ++ \", \" ++ plural(levels(t), \"level\")\n    counts = \"{wall(t)}{unit}, \" ++ seen\n    top = \"<text x=\\\"{inset}\\\" y=\\\"17\\\" fill=\\\"#f2f1f8\\\" font-weight=\\\"600\\\">\"\n    sub = \"<text x=\\\"{inset}\\\" y=\\\"31\\\" fill=\\\"#8d8c9b\\\">\"\n\n    back ++ top ++ name ++ \"</text>\\n\" ++ sub ++ counts ++ \"</text>\\n\"\n}\n\nsvg_frames(t: Trace, sc: Scale, inset: int, i: int, acc: str,\n           unit: str) -> str {\n    if i >= span_count(t) {\n        acc\n    } else {\n        svg_frames(t, sc, inset, i + 1,\n                   acc ++ svg_frame(t, sc, inset, i, unit), unit)\n    }\n}\n\nsvg_frame(t: Trace, sc: Scale, inset: int, i: int, unit: str) -> str {\n    s = t.spans.get(i)\n    left = inset + column(sc, s.start)\n    w = frame_width(sc, s, inset, left)\n    y = svg_head_h() + s.depth * svg_row()\n    tip = \"<title>\" ++ svg_tip(t, i, unit) ++ \"</title>\"\n    box = svg_rect(left, y, w, i)\n\n    \"<g>\" ++ tip ++ box ++ svg_label(s, left, y, w) ++ \"</g>\\n\"\n}\n\nframe_width(sc: Scale, s: Span, inset: int, left: int) -> int {\n    w = inset + column(sc, s.end) - left\n\n    w < 2 ? 2 : w\n}\n\nsvg_rect(x: int, y: int, w: int, i: int) -> str {\n    size = \"x=\\\"{x}\\\" y=\\\"{y}\\\" width=\\\"{w}\\\" height=\\\"{svg_row() - 3}\\\"\"\n    look = \"rx=\\\"2\\\" fill=\\\"{swatch(i)}\\\" stroke=\\\"#12121a\\\"\"\n\n    \"<rect {size} {look}/>\"\n}\n\nsvg_label(s: Span, x: int, y: int, w: int) -> str {\n    room = (w - 8) / 7\n\n    if room < 3 {\n        \"\"\n    } else {\n        text = escape_html(fit(s.name, room))\n        at = \"x=\\\"{x + 4}\\\" y=\\\"{y + svg_row() - 9}\\\"\"\n\n        \"<text {at} fill=\\\"#12121a\\\" font-weight=\\\"600\\\">\" ++ text ++ \"</text>\"\n    }\n}\n\nsvg_tip(t: Trace, i: int, unit: str) -> str {\n    s = t.spans.get(i)\n    share = percent(duration(s), wall(t))\n    own = \"self {self_time(t, i)}{unit}\"\n\n    escape_html(s.name) ++ \": {duration(s)}{unit} ({share:.1}%), \" ++ own\n}\n\n/// `part` as a percentage of `whole`, and zero rather than a division by zero when nothing was measured.\npercent(part: int, whole: int) -> float {\n    if whole <= 0 {\n        0.0\n    } else {\n        float(part) * 100.0 / float(whole)\n    }\n}\n\nswatch(i: int) -> str {\n    fills = [\"#7fd6d0\", \"#8fd694\", \"#e3cd7a\", \"#9db6ea\", \"#cba4dd\", \"#8ad4e8\"]\n\n    fills.get(i % fills.length())\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/profile/flame.maca"), profile_flame); const char* profile_play = "import profile/trace\n\n/// One end of one span.\nEvent = {\n    name: str,\n    at: int,\n    depth: int,\n    span: int,\n    enter: bool,\n}\n\n/// Every enter and leave in the trace, in the order they happened.\nevents(t: Trace) -> Event[] {\n    walked = walk_kids(t, roots(t), 0, [])\n\n    in_order(walked, 1) ? walked : by_time(walked, 0, [])\n}\n\nin_order(evs: Event[], i: int) -> bool {\n    if i >= evs.length() {\n        true\n    } else if evs.get(i).at < evs.get(i - 1).at {\n        false\n    } else {\n        in_order(evs, i + 1)\n    }\n}\n\nwalk_kids(t: Trace, ids: int[], i: int, acc: Event[]) -> Event[] {\n    if i >= ids.length() {\n        acc\n    } else {\n        walk_kids(t, ids, i + 1, walk_span(t, ids.get(i), acc))\n    }\n}\n\nwalk_span(t: Trace, i: int, acc: Event[]) -> Event[] {\n    s = t.spans.get(i)\n    inside = walk_kids(t, children(t, i), 0, acc.push(edge(s, i, true)))\n\n    inside.push(edge(s, i, false))\n}\n\nedge(s: Span, i: int, enter: bool) -> Event =>\n    Event {\n        name = s.name,\n        at = enter ? s.start : s.end,\n        depth = s.depth,\n        span = i,\n        enter = enter,\n    }\n\nby_time(evs: Event[], i: int, acc: Event[]) -> Event[] {\n    if i >= evs.length() {\n        acc\n    } else {\n        by_time(evs, i + 1, insert_by_time(acc, evs.get(i)))\n    }\n}\n\ninsert_by_time(acc: Event[], e: Event) -> Event[] {\n    at = first_later(acc, e.at, 0)\n    head = acc.slice(0, at).push(e)\n\n    head ++ acc.slice(at, acc.length())\n}\n\nfirst_later(acc: Event[], at: int, i: int) -> int {\n    if i >= acc.length() {\n        i\n    } else if acc.get(i).at > at {\n        i\n    } else {\n        first_later(acc, at, i + 1)\n    }\n}\n\n/// How many milliseconds separate event `i` from the one before it.\ngap_before(evs: Event[], i: int) -> int {\n    if i <= 0 || i >= evs.length() {\n        0\n    } else {\n        evs.get(i).at - evs.get(i - 1).at\n    }\n}\n\n/// Walk `evs` in time order, calling `on_event` with the index of each.\nreplay(evs: Event[], pace: int, on_event) -> int {\n    step(evs, pace, 0, on_event)\n\n    evs.length()\n}\n\nstep(evs: Event[], pace: int, i: int, on_event) -> int {\n    if i >= evs.length() {\n        i\n    } else {\n        wait = gap_before(evs, i) * pace / 100\n\n        if wait > 0 {\n            sleep_ms(wait)\n        }\n        on_event(i)\n        step(evs, pace, i + 1, on_event)\n    }\n}\n\n/// One event as a line: when it happened, how deep it was, and which way it went.\nnarrate_line(e: Event) -> str {\n    arrow = e.enter ? \"→\" : \"←\"\n    stamp = \"{e.at:>6}ms  \"\n\n    stamp ++ \"  \".repeat(e.depth) ++ arrow ++ \" \" ++ e.name\n}\n\n/// The whole trace as lines, one per event, in the order they happened.\nnarrate(t: Trace) -> str[] => narrate_all(events(t), 0, [])\n\nnarrate_all(evs: Event[], i: int, acc: str[]) -> str[] {\n    if i >= evs.length() {\n        acc\n    } else {\n        narrate_all(evs, i + 1, acc.push(narrate_line(evs.get(i))))\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/profile/play.maca"), profile_play); const char* profile_record = "import profile/trace\n\n/// One end of a region: the moment it opened or closed.\nMark = {\n    name: str,\n    at: int,\n    enter: bool,\n}\n\n/// A recording in progress.\nRec = {\n    label: str,\n    marks: Mark[],\n    open: int,\n}\n\n/// A fresh recorder.\nrecorder(label: str) -> Rec => Rec { label = label, marks = [], open = 0 }\n\n/// Open a region named `name`.\nstart(r: Rec, name: str) -> Rec =>\n    r with {\n        marks = r.marks.push(Mark { name = name, at = now_ms(), enter = true }),\n        open = r.open + 1,\n    }\n\n/// Close the innermost open region.\nstop(r: Rec) -> Rec =>\n    r with {\n        marks = r.marks.push(Mark { name = \"\", at = now_ms(), enter = false }),\n        open = r.open > 0 ? r.open - 1 : 0,\n    }\n\n/// A region around a call (`start`, the work, `stop`) with no way to forget the stop.\nspan(r: Rec, name: str, body) -> Rec =>\n    close_down_to(body(start(r, name)), r.open)\n\nclose_down_to(r: Rec, want: int) -> Rec {\n    if r.open <= want {\n        r\n    } else {\n        close_down_to(stop(r), want)\n    }\n}\n\n/// An instant rather than a region: a zero-length span at the current moment.\nmark(r: Rec, name: str) -> Rec {\n    at = now_ms()\n    opened = r.marks.push(Mark { name = name, at = at, enter = true })\n\n    r with { marks = opened.push(Mark { name = \"\", at = at, enter = false }) }\n}\n\n/// How many regions are open right now.\nopen_count(r: Rec) -> int => r.open\n\n/// Milliseconds since the first mark.\nelapsed(r: Rec) -> int {\n    n = r.marks.length()\n\n    n == 0 ? 0 : now_ms() - r.marks.get(0).at\n}\n\nBuild = {\n    spans: Span[],\n    open: int[],\n}\n\n/// The trace of everything recorded so far.\nfinish(r: Rec) -> Trace {\n    marks = r.marks\n\n    if marks.length() == 0 {\n        trace(r.label, [])\n    } else {\n        base = marks.get(0).at\n        built = build_spans(marks, base, 0, Build { spans = [], open = [] })\n        now = now_ms() - base\n\n        trace(r.label, extend_open(built.spans, built.open, 0, now))\n    }\n}\n\nbuild_spans(ms: Mark[], base: int, i: int, b: Build) -> Build {\n    if i >= ms.length() {\n        b\n    } else if ms.get(i).enter {\n        build_spans(ms, base, i + 1, opened(b, ms.get(i), base))\n    } else {\n        build_spans(ms, base, i + 1, ended(b, ms.get(i), base))\n    }\n}\n\nopened(b: Build, m: Mark, base: int) -> Build {\n    n = b.open.length()\n    inside = n > 0 ? b.open.get(n - 1) : -1\n    fresh = Span {\n        name = m.name,\n        start = m.at - base,\n        end = m.at - base,\n        depth = n,\n        parent = inside,\n        closed = false,\n    }\n\n    Build {\n        spans = b.spans.push(fresh),\n        open = b.open.push(b.spans.length()),\n    }\n}\n\nended(b: Build, m: Mark, base: int) -> Build {\n    n = b.open.length()\n\n    if n == 0 {\n        b\n    } else {\n        Build {\n            spans = closed_at(b.spans, b.open.get(n - 1), m.at - base),\n            open = b.open.slice(0, n - 1),\n        }\n    }\n}\n\nclosed_at(xs: Span[], i: int, at: int) -> Span[] {\n    xs[i] = xs.get(i) with { end = at, closed = true }\n    xs\n}\n\nextend_open(xs: Span[], open: int[], i: int, now: int) -> Span[] {\n    if i >= open.length() {\n        xs\n    } else {\n        at = open.get(i)\n        xs[at] = xs.get(at) with { end = now }\n        extend_open(xs, open, i + 1, now)\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/profile/record.maca"), profile_record); const char* profile_report = "import profile/trace\nimport { percent, fit } from profile/flame\nimport { bold, dim, grey, width, pad, pad_left } from cli/style\n\n/// One row: a name, and everything the run has to say about it.\nStat = {\n    name: str,\n    calls: int,\n    total: int,\n    own: int,\n    share: float,\n}\n\n/// Every name in the trace, heaviest self time first.\nsummary(t: Trace) -> Stat[] {\n    counted = tally(t, 0, [])\n    shared = with_shares(counted, wall(t), 0, [])\n\n    by_self(shared, 0, [])\n}\n\n/// The row for `name`, or a zeroed one if the trace never recorded it.\nstat_of(stats: Stat[], name: str) -> Stat {\n    at = index_named(stats, name, 0)\n\n    if at < 0 {\n        Stat { name = name, calls = 0, total = 0, own = 0, share = 0.0 }\n    } else {\n        stats.get(at)\n    }\n}\n\ntally(t: Trace, i: int, acc: Stat[]) -> Stat[] {\n    if i >= span_count(t) {\n        acc\n    } else {\n        tally(t, i + 1, charge(acc, t.spans.get(i), self_time(t, i)))\n    }\n}\n\ncharge(acc: Stat[], s: Span, own: int) -> Stat[] {\n    at = index_named(acc, s.name, 0)\n\n    if at < 0 {\n        acc.push(Stat {\n            name = s.name,\n            calls = 1,\n            total = duration(s),\n            own = own,\n            share = 0.0,\n        })\n    } else {\n        bump(acc, at, duration(s), own)\n    }\n}\n\nbump(acc: Stat[], at: int, ms: int, own: int) -> Stat[] {\n    was = acc.get(at)\n    now = was with {\n        calls = was.calls + 1,\n        total = was.total + ms,\n        own = was.own + own,\n    }\n\n    acc.slice(0, at).push(now) ++ acc.slice(at + 1, acc.length())\n}\n\nindex_named(stats: Stat[], name: str, i: int) -> int {\n    if i >= stats.length() {\n        -1\n    } else if stats.get(i).name == name {\n        i\n    } else {\n        index_named(stats, name, i + 1)\n    }\n}\n\nwith_shares(stats: Stat[], whole: int, i: int, acc: Stat[]) -> Stat[] {\n    if i >= stats.length() {\n        acc\n    } else {\n        s = stats.get(i)\n        with_shares(stats, whole, i + 1,\n                    acc.push(s with { share = percent(s.own, whole) }))\n    }\n}\n\nby_self(stats: Stat[], i: int, acc: Stat[]) -> Stat[] {\n    if i >= stats.length() {\n        acc\n    } else {\n        by_self(stats, i + 1, insert_by_self(acc, stats.get(i)))\n    }\n}\n\ninsert_by_self(acc: Stat[], s: Stat) -> Stat[] {\n    at = rank_of(acc, s.own, 0)\n    head = acc.slice(0, at).push(s)\n\n    head ++ acc.slice(at, acc.length())\n}\n\nrank_of(acc: Stat[], own: int, i: int) -> int {\n    if i >= acc.length() {\n        i\n    } else if acc.get(i).own < own {\n        i\n    } else {\n        rank_of(acc, own, i + 1)\n    }\n}\n\n/// The summary as a table: name, calls, total, self, share.\nsummary_table(t: Trace) -> str => stats_table(summary(t))\n\n/// The same table over rows the caller picked.\nstats_table(stats: Stat[]) -> str {\n    if stats.length() == 0 {\n        dim(\"(nothing recorded)\")\n    } else {\n        w = name_column(stats, 0, 4)\n        rows = body(stats, w, 0, [])\n\n        header(w) ++ rows.join(\"\\n\")\n    }\n}\n\nheader(w: int) -> str {\n    labels = row_text(\"span\", \"calls\", \"total\", \"self\", \"share\", w)\n    under = row_text(\"─\".repeat(w), \"─────\", \"────────\", \"────────\",\n                     \"───────\", w)\n\n    bold(labels) ++ \"\\n\" ++ grey(under) ++ \"\\n\"\n}\n\nbody(stats: Stat[], w: int, i: int, acc: str[]) -> str[] {\n    if i >= stats.length() {\n        acc\n    } else {\n        body(stats, w, i + 1, acc.push(stat_row(stats.get(i), w)))\n    }\n}\n\nstat_row(s: Stat, w: int) -> str =>\n    row_text(fit(s.name, w), str(s.calls), \"{s.total}ms\", \"{s.own}ms\",\n             \"{s.share:.1}%\", w)\n\nrow_text(name: str, calls: str, total: str, own: str, share: str,\n         w: int) -> str {\n    left = pad(name, w) ++ \"  \" ++ pad_left(calls, 5)\n    mid = \"  \" ++ pad_left(total, 8) ++ \"  \" ++ pad_left(own, 8)\n\n    left ++ mid ++ \"  \" ++ pad_left(share, 7)\n}\n\nname_column(stats: Stat[], i: int, best: int) -> int {\n    if i >= stats.length() {\n        best\n    } else if width(stats.get(i).name) > best {\n        name_column(stats, i + 1, width(stats.get(i).name))\n    } else {\n        name_column(stats, i + 1, best)\n    }\n}\n"; maca_write_file(maca_cat(maca_cat("", root), "/profile/report.maca"), profile_report); const char* profile_trace = "import std/json\n\n/// One timed region: when it opened, when it closed, how deep it sat, and which span it opened inside.\nSpan = {\n    name: str,\n    start: int,\n    end: int,\n    depth: int,\n    parent: int,\n    closed: bool,\n}\n\n/// A whole run: a label naming what was measured, and the spans in the order they were opened.\nTrace = {\n    label: str,\n    spans: Span[],\n}\n\n/// A trace from a label and a list of spans.\ntrace(label: str, spans: Span[]) -> Trace =>\n    Trace { label = label, spans = spans }\n\n/// A span, with the two fields most callers don't care about defaulted.\nregion(name: str, start: int, end: int) -> Span =>\n    Span {\n        name = name,\n        start = start,\n        end = end,\n        depth = 0,\n        parent = -1,\n        closed = true,\n    }\n\n/// How long a span lasted, in milliseconds.\nduration(s: Span) -> int => s.end - s.start\n\n/// How many spans the run recorded.\nspan_count(t: Trace) -> int => t.spans.length()\n\n/// The elapsed time of the whole run: the last end minus the first start.\nwall(t: Trace) -> int {\n    if t.spans.length() == 0 {\n        0\n    } else {\n        last_end(t.spans, 0, t.spans.get(0).end) - origin(t)\n    }\n}\n\n/// When the run began: the earliest moment any span opened.\norigin(t: Trace) -> int {\n    if t.spans.length() == 0 {\n        0\n    } else {\n        first_start(t.spans, 0, t.spans.get(0).start)\n    }\n}\n\nfirst_start(xs: Span[], i: int, best: int) -> int {\n    if i >= xs.length() {\n        best\n    } else if xs.get(i).start < best {\n        first_start(xs, i + 1, xs.get(i).start)\n    } else {\n        first_start(xs, i + 1, best)\n    }\n}\n\nlast_end(xs: Span[], i: int, best: int) -> int {\n    if i >= xs.length() {\n        best\n    } else if xs.get(i).end > best {\n        last_end(xs, i + 1, xs.get(i).end)\n    } else {\n        last_end(xs, i + 1, best)\n    }\n}\n\n/// The indices of the spans that are not inside any other, in the order they opened.\nroots(t: Trace) -> int[] => kids_of(t.spans, -1, 0, [])\n\n/// The indices of the spans opened directly inside span `i`, in the order they opened.\nchildren(t: Trace, i: int) -> int[] => kids_of(t.spans, i, 0, [])\n\nkids_of(xs: Span[], parent: int, i: int, acc: int[]) -> int[] {\n    if i >= xs.length() {\n        acc\n    } else if held_by(xs, i) == parent {\n        kids_of(xs, parent, i + 1, acc.push(i))\n    } else {\n        kids_of(xs, parent, i + 1, acc)\n    }\n}\n\nheld_by(xs: Span[], i: int) -> int {\n    p = xs.get(i).parent\n\n    p >= 0 && p < i ? p : -1\n}\n\n/// How many levels deep the run nested: 0 for an empty trace, 1 for a trace with no nesting at all.\nlevels(t: Trace) -> int => deepest(t.spans, 0, 0)\n\ndeepest(xs: Span[], i: int, best: int) -> int {\n    if i >= xs.length() {\n        best\n    } else if xs.get(i).depth + 1 > best {\n        deepest(xs, i + 1, xs.get(i).depth + 1)\n    } else {\n        deepest(xs, i + 1, best)\n    }\n}\n\n/// The indices of the spans at depth `d`, in the order they opened: one row of a flame chart.\nlevel(t: Trace, d: int) -> int[] => at_depth(t.spans, d, 0, [])\n\nat_depth(xs: Span[], d: int, i: int, acc: int[]) -> int[] {\n    if i >= xs.length() {\n        acc\n    } else if xs.get(i).depth == d {\n        at_depth(xs, d, i + 1, acc.push(i))\n    } else {\n        at_depth(xs, d, i + 1, acc)\n    }\n}\n\n/// The total time span `i` spent inside the regions it opened.\nchild_time(t: Trace, i: int) -> int => sum_kids(t, children(t, i), 0, 0)\n\nsum_kids(t: Trace, ids: int[], i: int, acc: int) -> int {\n    if i >= ids.length() {\n        acc\n    } else {\n        sum_kids(t, ids, i + 1, acc + duration(t.spans.get(ids.get(i))))\n    }\n}\n\n/// The time span `i` spent in its own code: its duration minus the time its children took.\nself_time(t: Trace, i: int) -> int {\n    own = duration(t.spans.get(i)) - child_time(t, i)\n\n    own > 0 ? own : 0\n}\n\n/// The names of the regions that were started and never stopped, outermost first.\nleaked(t: Trace) -> str[] => unclosed(t.spans, 0, [])\n\nunclosed(xs: Span[], i: int, acc: str[]) -> str[] {\n    if i >= xs.length() {\n        acc\n    } else if xs.get(i).closed {\n        unclosed(xs, i + 1, acc)\n    } else {\n        unclosed(xs, i + 1, acc.push(xs.get(i).name))\n    }\n}\n\n/// The index of the first span named `name`, or -1.\nfind_span(t: Trace, name: str) -> int => scan_name(t.spans, name, 0)\n\nscan_name(xs: Span[], name: str, i: int) -> int {\n    if i >= xs.length() {\n        -1\n    } else if xs.get(i).name == name {\n        i\n    } else {\n        scan_name(xs, name, i + 1)\n    }\n}\n\n/// The trace as JSON: a label and an array of span objects.\nto_json(t: Trace) -> str {\n    parts = span_objects(t.spans, 0, [])\n    body = parts.join(\",\")\n    head = \"\\{\\\"label\\\":\" ++ quote(t.label)\n\n    head ++ \",\\\"spans\\\":[\" ++ body ++ \"]\\}\"\n}\n\nspan_objects(xs: Span[], i: int, acc: str[]) -> str[] {\n    if i >= xs.length() {\n        acc\n    } else {\n        span_objects(xs, i + 1, acc.push(span_json(xs.get(i))))\n    }\n}\n\nspan_json(s: Span) -> str {\n    flag = s.closed ? \"true\" : \"false\"\n    when = \"\\\"start\\\":{s.start},\\\"end\\\":{s.end},\\\"depth\\\":{s.depth}\"\n    where = \"\\\"parent\\\":{s.parent},\\\"closed\\\":{flag}\"\n    head = \"\\{\\\"name\\\":\" ++ quote(s.name)\n\n    head ++ \",\" ++ when ++ \",\" ++ where ++ \"\\}\"\n}\n\n/// A trace read back from `to_json`.\nfrom_json(src: str) -> Trace =>\n    trace(get(src, \"label\"), read_spans(items(get(src, \"spans\")), 0, []))\n\nread_spans(objs: str[], i: int, acc: Span[]) -> Span[] {\n    if i >= objs.length() {\n        acc\n    } else {\n        read_spans(objs, i + 1, acc.push(read_span(objs.get(i))))\n    }\n}\n\nread_span(o: str) -> Span =>\n    Span {\n        name = get(o, \"name\"),\n        start = get_int(o, \"start\", 0),\n        end = get_int(o, \"end\", 0),\n        depth = get_int(o, \"depth\", 0),\n        parent = get_int(o, \"parent\", -1),\n        closed = get_bool(o, \"closed\"),\n    }\n"; return maca_write_file(maca_cat(maca_cat("", root), "/profile/trace.maca"), profile_trace);  }
