const char* llm_spec(const char* root) { return maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat(maca_cat("# Maca ", Version), "\n"), "\nOne typed language for programs and infrastructure config. "), "Everything you write is `.maca` or `maca.toml`.\n"), maca_cat(maca_cat("\nThe language section is `", SpecDoc), "` verbatim and the indexes are ")), "read out of the packages beside it, so neither can drift from the "), "tree this was run in.\n"), maca_cat(maca_cat("\n## The language\n\n", cheatsheet(maca_read_file(maca_cat(root, SpecDoc)))), "\n")), "\n## Whole programs\n\nEach compiles and runs as written.\n"), examples(root)), "\n## Mistakes to avoid\n"), mistakes()), "\n## Targets\n"), targets_table()), "\n## The standard library\n\nCarried beside the compiler, so "), "`import std/json` resolves anywhere. Every item below is one "), "`import` away.\n"), builtin_methods()), indexed(maca_cat(root, "modules/std"), "std", 0)), other_packages(root));  }
